// Funciones de UI/helpers que no afectan la lógica principal

// Escapa texto para insertarlo de forma segura dentro de HTML armado con
// template strings (innerHTML) — sin esto, cualquier dato tipeado por un
// usuario al reservar (nombre, teléfono, email, observaciones) podría
// inyectar HTML/JS que se ejecuta en la sesión de quien lo mire después
// (ej. el dueño del negocio abriendo el panel admin).
function escaparHtml(texto) {
    if (texto === null || texto === undefined) return '';
    return String(texto)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function mostrarError(mensaje) {
    document.querySelectorAll('.modal-error, .modal-overlay').forEach(el => el.remove());
    
    const overlay = document.createElement('div');
    overlay.className = 'modal-overlay';
    
    const modal = document.createElement('div');
    modal.className = 'modal-error';
    
    let mensajePersonalizado = mensaje;
    
    // Detectar conflictos de horario
    if (mensaje.includes('minutos') || mensaje.includes('horario')) {
        const duracionTotal = calcularDuracionTotal();
        const horas = Math.floor(duracionTotal / 60);
        const minutos = duracionTotal % 60;
        
        const textoDuracion = horas > 0 
            ? `${horas} hora${horas > 1 ? 's' : ''}${minutos > 0 ? ` y ${minutos} minutos` : ''}`
            : `${minutos} minutos`;
        
        mensajePersonalizado = `
            <svg viewBox="0 0 24 24" width="48" height="48" style="margin-bottom: 1rem;">
                <path fill="#ff6b6b" d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/>
            </svg>
            <h3>¡Cruce de horarios!</h3>
            <p>
                Tu turno necesita <strong>${textoDuracion}</strong> como mínimo.
                <br><br>
                Por favor, elegí otro horario donde entren todos tus servicios.
            </p>
        `;
    }
    
    modal.innerHTML = `
        ${mensajePersonalizado}
        <button id="cerrar-modal">¡Entendido!</button>
    `;
    
    // Agregar al DOM
    document.body.appendChild(overlay);
    document.body.appendChild(modal);
    
    // Cerrar al hacer clic
    const cerrarModal = () => {
        modal.style.animation = 'fadeIn 0.3s reverse';
        overlay.style.animation = 'fadeIn 0.3s reverse';
        setTimeout(() => {
            modal.remove();
            overlay.remove();
        }, 300);
    };
    
    modal.querySelector('#cerrar-modal').addEventListener('click', cerrarModal);
    overlay.addEventListener('click', cerrarModal);
}

// Modal de confirmación (reemplaza a confirm() nativo) con la misma estética
// que mostrarError(). Devuelve una Promise<boolean>: true si confirma.
//
// accionAsync (opcional): si se pasa, al confirmar el modal NO se cierra
// al toque — reemplaza sus botones por un loader, espera a que
// accionAsync() termine, y recién ahí se cierra. Antes (sin esto) el
// modal desaparecía apenas se hacía click en "confirmar", sin ninguna
// señal de que la acción todavía estaba corriendo — quien cancelaba un
// turno se quedaba sin saber si había funcionado hasta que aparecía (o
// no) la notificación final, que además podía tardar y quedar fuera de
// vista. accionAsync es responsable de su propio manejo de éxito/error
// (mostrar su propio toast, etc.) — este modal solo se encarga del loader
// y de cerrarse cuando termina, nunca queda trabado aunque explote algo.
function mostrarModalConfirmacion(mensaje, textoBotonAceptar = 'Sí, cancelar turno', accionAsync = null) {
    return new Promise((resolve) => {
        document.querySelectorAll('.modal-error, .modal-overlay').forEach(el => el.remove());

        const overlay = document.createElement('div');
        overlay.className = 'modal-overlay';

        const modal = document.createElement('div');
        modal.className = 'modal-error modal-confirmacion';

        modal.innerHTML = `
            <p>${mensaje}</p>
            <div class="modal-confirmacion-acciones">
                <button type="button" class="btn-confirmacion-volver">Volver</button>
                <button type="button" class="btn-confirmacion-aceptar">${textoBotonAceptar}</button>
            </div>
        `;

        document.body.appendChild(overlay);
        document.body.appendChild(modal);

        const cerrar = (resultado) => {
            modal.style.animation = 'fadeIn 0.3s reverse';
            overlay.style.animation = 'fadeIn 0.3s reverse';
            setTimeout(() => {
                modal.remove();
                overlay.remove();
                resolve(resultado);
            }, 300);
        };

        modal.querySelector('.btn-confirmacion-volver').addEventListener('click', () => cerrar(false));
        overlay.addEventListener('click', () => cerrar(false));

        modal.querySelector('.btn-confirmacion-aceptar').addEventListener('click', async () => {
            if (!accionAsync) {
                cerrar(true);
                return;
            }

            const acciones = modal.querySelector('.modal-confirmacion-acciones');
            acciones.innerHTML = '<div class="modal-confirmacion-loader"></div>';

            try {
                await accionAsync();
            } catch (error) {
                console.error('Error en la acción del modal de confirmación:', error);
                mostrarError('Ocurrió un error inesperado. Intentá de nuevo.');
            } finally {
                cerrar(true);
            }
        });
    });
}

// Sistema simple de manejo de errores
const ErrorHandler = {
    mostrar: (mensaje, tipo = 'error') => {
        
        // Usar tu función existente de mostrarError para errores
        if (tipo === 'error' && typeof mostrarError === 'function') {
            mostrarError(mensaje);
        }
        // Para advertencias, solo log en consola
        else if (tipo === 'warning') {
            console.warn(mensaje);
        }
    },

    manejarErrorFirestore: (error, contexto) => {
    console.error(`Error en ${contexto}:`, error);
    
    const mensajesPersonalizados = {
      'permission-denied': 'No tienes permisos para acceder a estos datos',
      'not-found': 'No se encontró la información solicitada',
      'unavailable': 'Error de conexión. Verifica tu internet',
      'failed-precondition': 'El servicio no está disponible en este momento'
    };
    
    const mensaje = mensajesPersonalizados[error.code] || 
                   `Error al ${contexto}. Intenta nuevamente.`;
    
    ErrorHandler.mostrar(mensaje, 'error');
    return []; // Retornar array vacío como fallback
  }
};

// Validaciones básicas para datos de Firestore
const Validador = {
    servicio: (servicio) => {
        if (!servicio || typeof servicio !== 'object') return false;
        
        const required = ['id', 'nombre', 'categoriaId'];
        return required.every(prop => servicio.hasOwnProperty(prop) && servicio[prop] != null);
    },

    especialista: (especialista) => {
        if (!especialista || typeof especialista !== 'object') return false;

        const required = ['id', 'nombre'];
        return required.every(prop => especialista.hasOwnProperty(prop) && especialista[prop] != null);
    },

    categoria: (categoria) => {
        if (!categoria || typeof categoria !== 'object') return false;
        return categoria.hasOwnProperty('id') && categoria.hasOwnProperty('nombre');
    },

    filtrarInvalidos: (datos, tipo) => {
        if (!Array.isArray(datos)) return [];
        return datos.filter(item => Validador[tipo](item));
    }
};


