// Función para inicializar el acordeón del menú

function inicializarAcordeonMenu() {
    const menuItems = document.querySelectorAll('.nav__list-item .menu');

    menuItems.forEach(menuItem => {
        // Esta función se vuelve a llamar cada vez que cambia la sesión
        // (actualizarVisibilidadMenu la reinvoca) — sin este guard, cada
        // llamada agregaba un listener más ENCIMA de los anteriores, sin
        // sacar los viejos. Con un número par de listeners acumulados, un
        // click abre y en el mismo evento vuelve a cerrar el submenú (cada
        // listener togglea "isActive" de nuevo), así que el menú parecía
        // no responder — bug real, encontrado al agregar la edición de
        // nombre de usuario (que dispara esta función una vez más).
        if (menuItem.dataset.acordeonWired) return;
        menuItem.dataset.acordeonWired = 'true';

        menuItem.addEventListener('click', function(e) {
            // Si el click fue en un elemento interactivo DENTRO del submenú
            // ya desplegado (ej. "Cancelar turno"), no togglear el acordeón
            // ni cortar la propagación — el handler delegado de ese botón
            // (en document) necesita recibir el evento. No confundir con un
            // click en el propio enlace del ítem de menú (que también podría
            // ser un <a>), por eso se exige que esté dentro de .submenu.
            if (e.target.closest('.submenu') && e.target.closest('button, a, input')) return;

            e.preventDefault();
            e.stopPropagation();

            const listItem = this.closest('.nav__list-item');
            const submenu = listItem.querySelector('.submenu');
            const isActive = submenu.classList.contains('active');

            cerrarTodosLosSubmenus();
            quitarClaseActiveNav();

            if (!isActive) {
                submenu.classList.add('active');
                this.classList.add('active');
                listItem.classList.add('active-nav');
            }
        });
    });

    // Cerrar menús solo al hacer clic FUERA del nav completo (una sola vez
    // — mismo motivo que el guard de arriba, esto también se re-llama).
    if (!document.body.dataset.cierreMenuAfueraWired) {
        document.body.dataset.cierreMenuAfueraWired = 'true';
        document.addEventListener('click', function(e) {
            if (!e.target.closest('.nav')) {
                cerrarTodosLosSubmenus();
                quitarClaseActiveNav();
            }
        });
    }

    // Manejar TODOS los elementos del submenu
    document.querySelectorAll('.submenu *').forEach(element => {
        if (element.dataset.submenuClickWired) return;
        element.dataset.submenuClickWired = 'true';

        element.addEventListener('click', function(e) {
            // No cortar la propagación para elementos interactivos: sus
            // propios handlers delegados (ej. cancelar turno, en document)
            // necesitan que el click burbujee hasta ahí para dispararse.
            if (e.target.closest('button, a, input')) return;
            e.stopPropagation(); // Prevenir que el clic cierre el menú
        });
    });
}

function inicializarCierreMenuOverlay() {
    document.addEventListener('click', function(e) {
        const body = document.body;
        if (!body.classList.contains('nav-active')) return;
        
        const nav = document.querySelector('.nav');
        const menuIcon = document.querySelector('.menu-icon');
        
        // Solo cerrar si el clic fue en el overlay (fondo)
        // No cerrar si fue en cualquier elemento dentro del nav
        if (!nav.contains(e.target) && !menuIcon.contains(e.target)) {
            // Pequeño delay para permitir que los eventos de los botones se ejecuten
            setTimeout(() => {
                body.classList.remove('nav-active');
            }, 10);
        }
    });
    
    // NO prevenir la propagación para elementos interactivos
    // Esto permite que los botones dentro del menú funcionen normalmente
    const navElement = document.querySelector('.nav');
    if (navElement) {
        navElement.addEventListener('click', function(e) {
            // Solo prevenir propagación para elementos no interactivos
            if (!e.target.closest('button') && 
                !e.target.closest('a') && 
                !e.target.closest('input')) {
                e.stopPropagation();
            }
        });
    }
    
    // Cerrar con tecla ESC
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && document.body.classList.contains('nav-active')) {
            document.body.classList.remove('nav-active');
        }
    });
}

// Función para quitar la clase active-nav de todos los items
function quitarClaseActiveNav() {
    document.querySelectorAll('.nav__list-item').forEach(item => {
        item.classList.remove('active-nav');
    });
}

// Función para cerrar todos los submenús
function cerrarTodosLosSubmenus() {
    document.querySelectorAll('.submenu').forEach(submenu => {
        submenu.classList.remove('active');
    });
    
    document.querySelectorAll('.menu').forEach(menu => {
        menu.classList.remove('active');
    });
}

