// Función para obtener datos de contacto SIN event listeners
function obtenerDatosContactoSeguro() {
    // Intentar desde window.datosGenerales primero
    if (window.datosGenerales && window.datosGenerales.empresa) {
        return window.datosGenerales.empresa;
    }
    
    // Intentar desde la variable global de app.js
    if (typeof datosGenerales !== 'undefined' && datosGenerales.empresa) {
        return datosGenerales.empresa;
    }
    
    // Último intento: buscar en localStorage si ya los cargamos antes
    const contactoCache = localStorage.getItem('contactoCache');
    if (contactoCache) {
        try {
            return JSON.parse(contactoCache);
        } catch (e) {
            console.warn('Cache de contacto corrupto');
        }
    }
    
    return null;
}

// Optimizar actualizarMenuContacto para usar cache
function actualizarMenuContacto(empresa) {
    if (!empresa) return false;
    
    try {
        // Guardar en cache para próximas cargas
        localStorage.setItem('contactoCache', JSON.stringify(empresa));

        // Actualizar nombre del negocio
        const nombreElement = document.getElementById('menu-nombre');
        if (nombreElement && empresa.nombre) {
            nombreElement.textContent = empresa.nombre;
        }

        // Logo/foto del negocio, si el dueño cargó uno desde el panel
        const logoElement = document.getElementById('menu-logo');
        if (logoElement) {
            if (empresa.logoUrl) {
                logoElement.src = empresa.logoUrl;
                logoElement.alt = empresa.nombre || '';
                logoElement.style.display = '';
            } else {
                logoElement.style.display = 'none';
            }
        }

        // Actualizar dirección
        const direccionElement = document.getElementById('menu-direccion');
        if (direccionElement && empresa.direccion) {
            direccionElement.textContent = empresa.direccion;
        }

        // Actualizar horario de atención
        const horarioElement = document.getElementById('menu-horario');
        if (horarioElement && empresa.horariosAtencion) {
            horarioElement.textContent = empresa.horariosAtencion;
        }

        // Actualizar teléfono
        const telefonoElement = document.getElementById('menu-telefono');
        if (telefonoElement && empresa.telefono) {
            telefonoElement.textContent = empresa.telefono;
        }

        // Actualizar email
        const emailElement = document.getElementById('menu-email');
        if (emailElement && empresa.email) {
            emailElement.textContent = empresa.email;
        }

        // Actualizar redes sociales — el ícono queda siempre visible; si no
        // hay URL cargada para esa red, no navega a ningún lado al
        // clickearlo (mismo criterio que el resumen final, ver
        // actualizarLinkRedSocial en app.js).
        const redes = empresa.redes || {};
        actualizarLinkRedSocial(document.getElementById('menu-instagram'), redes.instagram);
        actualizarLinkRedSocial(document.getElementById('menu-whatsapp'), redes.whatsapp);
        actualizarLinkRedSocial(document.getElementById('menu-equis'), redes.x);

        return true;
        
    } catch (error) {
        console.error('❌ Error actualizando menú contacto:', error);
        return false;
    }
}

// SOLUCIÓN DEFINITIVA: Solo cargar datos periódicamente SIN NINGÚN EVENT LISTENER
function inicializarMenuContactoDefinitivo() {
    
    // Cargar UNA sola vez con un delay generoso
    setTimeout(() => {
        const empresa = obtenerDatosContactoSeguro();
        const exito = actualizarMenuContacto(empresa);
        
        if (exito) {
        } else {
            // Si falla, intentar una vez más después de 5 segundos
            setTimeout(() => {
                const empresa = obtenerDatosContactoSeguro();
                actualizarMenuContacto(empresa);
            }, 5000);
        }
    }, 3000);
    
    // 🔥 ELIMINADO: No más setInterval para el contacto
    // Los datos de contacto son estáticos, no necesitan actualización constante
}

