// Función para formatear la fecha en español
function formatearFecha(fechaStr) {
  const fecha = new Date(fechaStr + 'T00:00:00');
  const dias = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
  const meses = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
  
  const diaSemana = dias[fecha.getDay()];
  const diaMes = fecha.getDate();
  const mes = meses[fecha.getMonth()];
  
  return `${diaSemana} ${diaMes} ${mes}`;
}

// Función para calcular horario de fin
function calcularHorarioFin(horarioInicio, duracionMinutos) {
  const [horas, minutos] = horarioInicio.split(':').map(Number);
  const totalMinutos = horas * 60 + minutos + duracionMinutos;
  
  const horasFin = Math.floor(totalMinutos / 60);
  const minutosFin = totalMinutos % 60;
  
  return `${horasFin.toString().padStart(2, '0')}:${minutosFin.toString().padStart(2, '0')}`;
}

// Función para cargar y mostrar los turnos del usuario
async function cargarTurnosUsuario() {
  const usuario = firebase.auth().currentUser;
  if (!usuario) return;

  const submenuUl = document.querySelector('#nav-mis-turnos .submenu ul');
  if (!submenuUl) return;

  try {
    // Actualizar timestamp de última carga
    ultimaCargaTurnos = Date.now();

    // Mostrar loading solo si no hay datos previos
    if (!submenuUl.querySelector('.turno-item')) {
      submenuUl.innerHTML = '<li><p>Cargando turnos...</p></li>';
    }

    const turnos = await window.firestoreDB.obtenerTurnosPorUsuario(usuario.uid);
    
    if (turnos.length === 0) {
      submenuUl.innerHTML = '<li><p>No tenés turnos reservados</p></li>';
      return;
    }

    // Generar HTML de los turnos
    const turnosHTML = turnos.map(turno => {
      const fechaFormateada = formatearFecha(turno.fecha);
      const horarioFin = calcularHorarioFin(turno.horarioInicio, turno.duracionTotal || 30);
      const montoFormateado = turno.montoTotal ? `$${turno.montoTotal.toLocaleString('es-AR')}` : 'Sin señar';

      // Mismo dato que ya arma el mail de confirmación (ver
      // _resolverDatosEmailTurno en functions/index.js) — sin esto, "Mis
      // turnos" solo mostraba fecha/hora/monto, y era fácil olvidarse para
      // qué servicio era cada reserva.
      const nombresServicios = Object.values(turno.serviciosPorEspecialista || {})
        .flat()
        .map(s => s.nombre)
        .filter(Boolean)
        .join(', ') || 'Servicio no especificado';

      // Mismo corte de 24hs que usa cancelarTurnoUsuario() en firestore.js:
      // si ya no se puede cancelar, ni mostramos el botón (clickearlo no
      // haría nada útil).
      const puedeCancelar = horasHastaFechaHora(turno.fecha, turno.horarioInicio) >= 24;
      const accionCancelar = puedeCancelar
        ? `<button type="button" class="btn-cancelar-turno" data-turno-id="${turno.id}">Cancelar turno</button>`
        : `<span class="turno-no-cancelable">No cancelable (falta menos de 24hs)</span>`;

      return `
        <li class="turno-item" data-turno-id="${turno.id}">
          <p><strong>${fechaFormateada}</strong> de ${turno.horarioInicio} a ${horarioFin}</p>
          <p style="margin-top: 4px;">${nombresServicios}</p>
          <p class="turno-precio" style="margin-top: 4px; font-weight: 500;">${montoFormateado}</p>
          ${accionCancelar}
        </li>
      `;
    }).join('');

    submenuUl.innerHTML = turnosHTML;

  } catch (error) {
    console.error('Error cargando turnos:', error);
    // Solo mostrar error si no hay datos previos
    if (!submenuUl.querySelector('.turno-item')) {
      submenuUl.innerHTML = '<li><p>Error al cargar turnos</p></li>';
    }
  }
}

// Delegado: manejar clicks en "Cancelar turno" dentro del menú de Mis Turnos
document.addEventListener('click', async (e) => {
  const boton = e.target.closest('.btn-cancelar-turno');
  if (!boton) return;

  const turnoId = boton.dataset.turnoId;
  const usuario = firebase.auth().currentUser;
  if (!usuario) return;

  await mostrarModalConfirmacion(
    '¿Seguro que querés cancelar este turno? Esta acción no se puede deshacer.',
    'Sí, cancelar turno',
    async () => {
      const resultado = await window.firestoreDB.cancelarTurnoUsuario(turnoId, usuario.uid);
      if (resultado.success) {
        forzarActualizacionTurnos();
        mostrarMensajeExito('Turno cancelado correctamente');

        // Si esta cancelación generó crédito, que se refleje ya mismo en
        // el resumen de la reserva en curso (si hay uno visible) — antes
        // quedaba con el crédito viejo hasta el próximo avanzarPaso(), y
        // si el cliente ya estaba parado en un paso sin volver a
        // avanzar, nunca se enteraba sin recargar la página entera.
        if (typeof refrescarCreditoDisponible === 'function') {
          await refrescarCreditoDisponible(usuario.uid);
        }
        if (typeof actualizarResumenServicios === 'function') {
          actualizarResumenServicios();
        }
      } else {
        mostrarError(resultado.mensaje || 'No se pudo cancelar el turno.');
      }
    }
  );
});

// Función para inicializar el sistema de turnos del usuario
function inicializarSistemaTurnosUsuario() {
  
  // Cargar turnos cuando el usuario inicie sesión
  firebase.auth().onAuthStateChanged((user) => {
    if (user) {
      // Cargar turnos inicialmente
      setTimeout(() => {
        cargarTurnosUsuario();
      }, 1000);
      
      // Configurar observador para el menú
      configurarObservadorMenu();
    } else {
      // Limpiar intervalo si existe
      detenerActualizacionAutomatica();
    }
  });
}

function configurarObservadorMenu() {
  // Observar cambios en la clase del body para detectar cuando se abre/cierra el menú
  const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      if (mutation.attributeName === 'class') {
        const body = document.body;
        if (body.classList.contains('nav-active')) {
          // Menú abierto - cargar solo si los datos son antiguos
          const ahora = Date.now();
          if (ahora - ultimaCargaTurnos > CACHE_DURACION) {
            cargarTurnosUsuario();
          }
          
          // Iniciar actualizaciones lentas (solo cuando el menú está abierto)
          iniciarActualizacionAutomatica();
        } else {
          // Menú cerrado - detener actualizaciones
          detenerActualizacionAutomatica();
        }
      }
    });
  });
  
  observer.observe(document.body, { attributes: true });
}

function iniciarActualizacionAutomatica() {
  // Si ya hay un intervalo activo, no crear otro
  if (intervaloActualizacionTurnos) return;
  
  
  // Actualizar cada 5 minutos (en lugar de 30 segundos)
  intervaloActualizacionTurnos = setInterval(() => {
    cargarTurnosUsuario();
  }, 300000); // 5 minutos
}

function detenerActualizacionAutomatica() {
  if (intervaloActualizacionTurnos) {
    clearInterval(intervaloActualizacionTurnos);
    intervaloActualizacionTurnos = null;
  }
}

// Función para forzar recarga manual (útil para después de nuevas reservas)
function forzarActualizacionTurnos() {
  ultimaCargaTurnos = 0; // Invalidar caché
  cargarTurnosUsuario();
}

// Mueve el mensaje de los íconos informativos (.info-tooltip) a <body>
// cuando se muestran, calculando su posición con JS en lugar de
// position:absolute relativo a su propio padre. Hace falta porque
// .contenedor-maqueta (el contenedor con scroll del flujo de reserva)
// tiene overflow-y:auto, que recorta cualquier hijo posicionado que se
// desborde — el recorte por overflow ocurre en el layout, antes del
// apilamiento, así que ningún z-index puede evitarlo. Con position:fixed
// y el elemento como hijo directo de <body>, ese recorte deja de aplicar.
function inicializarTooltipsFlotantes() {
    document.querySelectorAll('.info-tooltip').forEach(trigger => {
        const texto = trigger.querySelector('.info-tooltip-texto');
        if (!texto) return;

        const posicionar = () => {
            if (texto.parentElement !== document.body) {
                document.body.appendChild(texto);
            }

            const rectIcono = trigger.getBoundingClientRect();
            const margen = 8;

            // Centrado sobre el ícono, ajustado para no salirse de la ventana
            let left = rectIcono.left + rectIcono.width / 2 - texto.offsetWidth / 2;
            left = Math.max(margen, Math.min(left, window.innerWidth - texto.offsetWidth - margen));
            const top = Math.max(margen, rectIcono.top - texto.offsetHeight - 10);

            texto.style.left = `${left}px`;
            texto.style.top = `${top}px`;

            // La flecha sigue apuntando al centro del ícono aunque el
            // tooltip se haya desplazado para no salirse de la pantalla
            const centroIcono = rectIcono.left + rectIcono.width / 2;
            texto.style.setProperty('--info-tooltip-flecha', `${centroIcono - left}px`);
        };

        const mostrar = () => {
            posicionar();
            texto.classList.add('visible');
        };
        const ocultar = () => texto.classList.remove('visible');

        trigger.addEventListener('mouseenter', mostrar);
        trigger.addEventListener('mouseleave', ocultar);
        trigger.addEventListener('focus', mostrar);
        trigger.addEventListener('blur', ocultar);
        window.addEventListener('scroll', () => {
            if (texto.classList.contains('visible')) posicionar();
        }, { capture: true, passive: true });
    });
}

// Inicializar SIN event listeners de ningún tipo
document.addEventListener('DOMContentLoaded', function() {
    inicializarMenuContactoDefinitivo();
    inicializarSistemaTurnosUsuario();
    inicializarTooltipsFlotantes();
});