    function inicializarTabBar() {
      const navAdmin = document.querySelector('.nav-admin');
      const enlaces = navAdmin.querySelectorAll('.nav-enlace');
      const overlay = navAdmin.querySelector('.nav-enlace-overlay');
      
      // Función para activar un enlace
      function activarEnlace(enlace) {
        enlaces.forEach(e => e.classList.remove('active'));
        enlace.classList.add('active');
        
        // ✅ CORREGIDO: Considerar el padding del enlace en el cálculo
        const rect = enlace.getBoundingClientRect();
        const navRect = navAdmin.getBoundingClientRect();
        
        // Obtener el padding del enlace
        const enlaceStyles = getComputedStyle(enlace);
        const paddingLeft = parseFloat(enlaceStyles.paddingLeft);
        const paddingRight = parseFloat(enlaceStyles.paddingRight);
        
        // Calcular posición y tamaño CONSIDERANDO el padding
        const overlayLeft = (rect.left - navRect.left) - paddingLeft;
        const overlayWidth = rect.width + paddingRight;
        
        overlay.style.width = `${overlayWidth}px`;
        overlay.style.left = `${overlayLeft}px`;
      }
      
      // Agregar event listeners
      enlaces.forEach(enlace => {
        enlace.addEventListener('click', () => activarEnlace(enlace));
      });
      
      // Inicializar posición del overlay
      const activeEnlace = navAdmin.querySelector('.nav-enlace.active');
      if (activeEnlace) {
        setTimeout(() => activarEnlace(activeEnlace), 100);
      }

      window.addEventListener('resize', () => {
        const currentActive = navAdmin.querySelector('.nav-enlace.active');
        if (currentActive) {
          setTimeout(() => activarEnlace(currentActive), 50);
        }
      });
    }

