    async function cargarServicios() {
      try {
        const snapshot = await db.collection('servicios').where('negocioId', '==', obtenerNegocioIdActual()).get();
        serviciosMap = {};
        snapshot.forEach(doc => {
          serviciosMap[doc.id] = doc.data();
        });
      } catch (error) {
        console.error("Error cargando servicios:", error);
      }
    }

    async function cargarEspecialistas() {
      try {
        especialistasCargando = true;
        
        const snapshot = await db.collection('especialistas').where('negocioId', '==', obtenerNegocioIdActual()).get();
        const nuevoMapa = {};
        
        
        let cargados = 0;
        snapshot.forEach(doc => {
          const data = doc.data();
          nuevoMapa[doc.id] = data;
          cargados++;
        });
        
        // Actualizar el mapa de forma atómica
        especialistasMap = { ...especialistasMap, ...nuevoMapa };
        
        
        // Reprocesar eventos pendientes si los hay
        if (pendientesDeActualizacion.length > 0) {
          pendientesDeActualizacion.forEach(callback => callback());
          pendientesDeActualizacion = [];
        }
        
        return cargados;
      } catch (error) {
        console.error("❌ Error cargando especialistas:", error);
        return 0;
      } finally {
        especialistasCargando = false;
      }
    }

    // Traduce el estado crudo del turno a texto legible + una clase CSS
    // para el color del badge. 'pendiente' queda como caso heredado (no
    // debería aparecer en turnos nuevos desde el fix de estado inicial en
    // firestore.js, pero turnos viejos ya guardados en la base sí lo tienen).
    function formatearEstadoTurno(estado) {
      const mapa = {
        confirmado: { texto: 'Confirmado', clase: 'estado-confirmado' },
        pendiente_pago: { texto: 'Pendiente de pago', clase: 'estado-pendiente-pago' },
        pendiente: { texto: 'Pendiente', clase: 'estado-pendiente' }
      };
      return mapa[estado] || { texto: estado || 'Pendiente', clase: 'estado-pendiente' };
    }

    function obtenerNombreEspecialista(especialistaId) {
      if (!especialistaId || especialistaId === 'sin-especialista') {
        return 'Sin especialista asignado';
      }
      
      // Verificar si ya tenemos el especialista en el mapa
      const especialista = especialistasMap[especialistaId];
      if (especialista && especialista.nombre) {
        return especialista.nombre;
      }
      
      // Si no está en el mapa, intentar cargarlo bajo demanda
      if (!especialistasCargando) {
        cargarEspecialistaIndividual(especialistaId);
      }
      
      // Mientras se carga, devolver el ID formateado como fallback temporal
      return formatearNombreDesdeId(especialistaId);
    }

    async function cargarEspecialistaIndividual(especialistaId) {
      try {
        const doc = await db.collection('especialistas').doc(especialistaId).get();
        if (doc.exists) {
          const data = doc.data();
          // Actualizar el mapa
          especialistasMap[especialistaId] = data;
          
          // Refrescar el calendario para mostrar los nombres actualizados
          if (calendar) {
            calendar.refetchEvents();
          }
        }
      } catch (error) {
        console.error(`❌ Error cargando especialista individual ${especialistaId}:`, error);
      }
    }

    function formatearNombreDesdeId(especialistaId) {
      // Remover prefijo "esp_" y reemplazar guiones bajos por espacios
      let nombre = especialistaId.replace(/^esp_/, '');
      nombre = nombre.replace(/_/g, ' ');
      
      // Capitalizar palabras
      nombre = nombre.replace(/\w\S*/g, function(txt) {
        return txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase();
      });
      
      return nombre;
    }

    async function recargarEspecialistasYVista() {
      await cargarEspecialistas();
      if (calendar) {
        calendar.refetchEvents();
      }
    }

    async function obtenerConfiguracion() {
      try {
        const doc = await db.collection('negocios').doc(obtenerNegocioIdActual()).get();
        if (!doc.exists) return obtenerConfiguracionPorDefecto();
        
        const data = doc.data();
        
        // Función robusta para normalizar días laborales
        const normalizarDias = (dias) => {
          if (!dias) return [1,2,3,4,5];
          
          // Si ya es un array de números, devolverlo
          if (Array.isArray(dias) && dias.every(item => typeof item === 'number')) {
            return dias;
          }
          
          // Si es un string que parece contener un array
          if (typeof dias === 'string') {
            try {
              // Limpiar el string
              const strClean = dias.trim().replace(/[\[\]'"\s]/g, '');
              if (strClean === '') return [1,2,3,4,5];
              
              // Convertir a array de números
              return strClean.split(',').map(Number).filter(n => !isNaN(n) && n >= 0 && n <= 6);
            } catch (e) {
              console.warn("Error parseando días laborales:", e);
              return [1,2,3,4,5];
            }
          }
          
          // Si es un array con strings
          if (Array.isArray(dias)) {
            return dias.map(item => {
              if (typeof item === 'number') return item;
              if (typeof item === 'string') {
                return parseInt(item.replace(/\D/g, ''), 10);
              }
              return null;
            }).filter(n => !isNaN(n) && n >= 0 && n <= 6);
          }
          
          return [1,2,3,4,5]; // Default
        };
        
        const diasLaborales = normalizarDias(data.diasLaborales)
          .filter(n => n >= 0 && n <= 6) // Filtrar valores inválidos
          .sort((a, b) => a - b); // Ordenar
        
        return {
          horarioApertura: data.horarioApertura || "09:00",
          horarioCierre: data.horarioCierre || "19:00",
          duracionTurno: data.duracionTurno || 30,
          diasLaborales: diasLaborales.length > 0 ? diasLaborales : [1,2,3,4,5]
        };
      } catch (error) {
        console.error("Error obteniendo configuración:", error);
        return obtenerConfiguracionPorDefecto();
      }
    }

    function obtenerConfiguracionPorDefecto() {
      return {
        horarioApertura: "09:00",
        horarioCierre: "19:00",
        duracionTurno: 30,
        diasLaborales: [1,2,3,4,5] // Lunes a Viernes
      };
    }

    function validarHorario(horario, config) {
      // Convertir horario a minutos desde medianoche
      const [horas, minutos] = horario.split(':').map(Number);
      const horarioEnMinutos = horas * 60 + minutos;
      
      // Convertir horarios de apertura/cierre
      const [aperturaH, aperturaM] = config.horarioApertura.split(':').map(Number);
      const [cierreH, cierreM] = config.horarioCierre.split(':').map(Number);
      const aperturaEnMinutos = aperturaH * 60 + aperturaM;
      const cierreEnMinutos = cierreH * 60 + cierreM;
      
      // Validar que esté dentro del horario laboral
      if (horarioEnMinutos < aperturaEnMinutos || horarioEnMinutos >= cierreEnMinutos) {
        return {
          valido: false,
          mensaje: `El horario debe estar entre ${config.horarioApertura} y ${config.horarioCierre}`
        };
      }
      
      // Validar que sea en intervalos de 30 minutos
      if (minutos % config.duracionTurno !== 0) {
        return {
          valido: false,
          mensaje: `Los turnos deben ser en intervalos de ${config.duracionTurno} minutos (ej: 09:00, 09:30, etc.)`
        };
      }
      
      return { valido: true };
    }

    async function initCalendar() {
      if (!elements.calendar) return;
      
      calendar = new FullCalendar.Calendar(elements.calendar, {
        initialView: 'dayGridMonth',
        locale: 'es',
        headerToolbar: {
          left: 'prev,next today',
          center: 'title',
          right: 'dayGridMonth,timeGridWeek,timeGridDay'
        },
        selectable: true,
        selectMirror: true,
        dayMaxEvents: true,
        selectOverlap: false,

        // El texto de este link ("+1 más") es contenido que FullCalendar
        // arma internamente — no hay forma de recortarlo solo con CSS
        // (no se puede saber el número de antemano para un content: fijo).
        // moreLinkContent es la opción que FullCalendar expone
        // justamente para esto: reemplaza el texto por únicamente el
        // número, el círculo que lo rodea sí es 100% CSS (.fc-daygrid-more-link).
        moreLinkContent: (args) => `${args.num}`,
        
        height: 'auto', // Altura automática
        contentHeight: 'auto', // Altura del contenido automática

        allDaySlot: false, // Ocultar la ranura "todo el día"
        slotMinTime: "09:00:00", // Ajustar según tu horario de apertura
        slotMaxTime: "20:00:00", // Ajustar según tu horario de cierre
        slotDuration: "00:30:00", // Duración de cada slot (30 minutos)
        slotLabelInterval: "01:00:00", // Mostrar etiquetas cada hora
        slotLabelFormat: {
          hour: '2-digit',
          minute: '2-digit',
          hour12: false
        },
        
        // Modificar el evento dateClick en initCalendar
        dateClick: async function(info) {
          // Remover la clase de selección de todas las celdas primero
          document.querySelectorAll('.fc-daygrid-day-selected').forEach(el => {
            el.classList.remove('fc-daygrid-day-selected');
          });
          
          // Añadir la clase de selección a la celda clickeada
          info.dayEl.classList.add('fc-daygrid-day-selected');
          
          // Buscar el enlace "more" (contador) en este día
          const moreLink = info.dayEl.querySelector('.fc-daygrid-more-link');
          
          if (moreLink) {
            // Si hay contador, simular click en él para abrir el popover
            moreLink.click();
          } else {
            // Si no hay contador, verificar si hay eventos en este día
            const events = calendar.getEvents().filter(event => {
              const eventStart = event.start;
              return eventStart &&
                    formatearFechaLocal(eventStart) === info.dateStr &&
                    !event.extendedProps.esContador; // Excluir eventos contador
            });
            
            if (events.length > 0) {
              // Si hay eventos pero no contador (menos del límite), mostrar en el panel lateral
              await loadTurnosForDate(info.dateStr);
            } else {
              // Si no hay eventos, también cargar en el panel lateral (mostrará "No hay turnos")
              await loadTurnosForDate(info.dateStr);
            }
          }
        },
        
        events: async function(fetchInfo, successCallback, failureCallback) {
          try {
            const snapshot = await db.collection('turnos')
              .where('negocioId', '==', obtenerNegocioIdActual())
              .where('fecha', '>=', fetchInfo.startStr)
              .where('fecha', '<=', fetchInfo.endStr)
              .get();

            const privadosPorId = await obtenerDatosPrivadosTurnos(snapshot.docs.map(doc => doc.id));
            const events = [];

            snapshot.docs.forEach(doc => {
              const data = { ...doc.data(), ...(privadosPorId[doc.id] || {}) };
              const clienteNombre = data.cliente?.nombre || 'Cliente no especificado';
              const serviciosNombres = obtenerNombresServicios(data.serviciosIds);
              
              // Manejar múltiples especialistas
              const especialistaIds = data.especialistaIds || [];
              
              if (especialistaIds.length === 0) {
                // Caso sin especialistas
                const horario = data.horario || data.horarioInicio || '00:00';
                events.push(crearEventoTurno(doc.id, data, clienteNombre, serviciosNombres, 'sin-especialista', horario, horario));
              } else if (especialistaIds.length === 1) {
                // Caso con un solo especialista
                const especialistaId = especialistaIds[0];
                const horario = data.horario || data.horarioInicio || '00:00';
                events.push(crearEventoTurno(doc.id, data, clienteNombre, serviciosNombres, especialistaId, horario, horario));
              } else {
                // Caso con múltiples especialistas - crear un evento por cada uno
                especialistaIds.forEach(especialistaId => {
                  let horarioInicio = data.horarioInicio;
                  let horarioFin = data.horarioInicio;
                  
                  if (data.slotsPorEspecialista && data.slotsPorEspecialista[especialistaId]) {
                    const slots = data.slotsPorEspecialista[especialistaId];
                    if (slots.length > 0) {
                      horarioInicio = slots[0];
                      
                      // Calcular duración específica para este especialista
                      let duracion = 30; // Default
                      if (data.serviciosPorEspecialista && data.serviciosPorEspecialista[especialistaId]) {
                        const serviciosEspecialista = data.serviciosPorEspecialista[especialistaId];
                        duracion = serviciosEspecialista.reduce((total, servicio) => total + (servicio.duracion || 30), 0);
                      }
                      
                      // Calcular horario fin preciso
                      const [hora, minuto] = horarioInicio.split(':').map(Number);
                      const inicioMinutos = hora * 60 + minuto;
                      const finMinutos = inicioMinutos + duracion;
                      const horaFin = Math.floor(finMinutos / 60).toString().padStart(2, '0');
                      const minutoFin = (finMinutos % 60).toString().padStart(2, '0');
                      horarioFin = `${horaFin}:${minutoFin}`;
                    }
                  }
                  
                  // Obtener servicios específicos para este especialista
                  let serviciosEspecificos = serviciosNombres;
                  if (data.serviciosPorEspecialista && data.serviciosPorEspecialista[especialistaId]) {
                    const servicios = data.serviciosPorEspecialista[especialistaId];
                    serviciosEspecificos = servicios.map(s => s.nombre).join(', ');
                  }
                  
                  events.push(crearEventoTurno(
                    `${doc.id}_${especialistaId}`, // ID único del EVENTO (solo para FullCalendar)
                    data,
                    clienteNombre,
                    serviciosEspecificos,
                    especialistaId,
                    horarioInicio,
                    horarioFin,
                    true, // Es múltiple
                    doc.id // ID real del turno en Firestore
                  ));
                });
              }
            });
            
            successCallback(events);
          } catch (error) {
            console.error("Error cargando eventos:", error);
            successCallback([]);
          }
        },
        
        eventClick: function(info) {
          abrirModalEdicion(info.event);
        },
        
        select: function(info) {
          calendar.unselect();
        },
        
        // Configuración específica para cada vista
        views: {
          dayGridMonth: {
            dayMaxEvents: 0,
            dayMaxEventRows: 1, // Límite de eventos por día en vista mensual
            displayEventTime: false, // No mostrar hora en eventos de vista mensual
          },
          timeGridWeek: {
            dayHeaderFormat: { weekday: 'short', day: 'numeric', month: 'short' },
            slotEventOverlap: false, // Evitar superposición visual de eventos
            eventMinHeight: 20, // Altura mínima para eventos cortos
            allDaySlot: false // Ocultar "todo el día" en vista semanal
          },
          timeGridDay: {
            dayHeaderFormat: { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' },
            slotEventOverlap: false,
            eventMinHeight: 20,
            allDaySlot: false
          }
        },
        
        // Asegurar que los eventos usen la duración correcta
        eventTimeFormat: {
          hour: '2-digit',
          minute: '2-digit',
          hour12: false
        },
        
        // Limpiar selección al cambiar de vista
        viewDidMount: function() {
          document.querySelectorAll('.fc-daygrid-day-selected').forEach(el => {
            el.classList.remove('fc-daygrid-day-selected');
          });
        },
        
        // Mejorar el tooltip para mostrar duración
        eventDidMount: function(info) {
          const { event } = info;
          const startTime = event.start.toLocaleTimeString('es-ES', { 
            hour: '2-digit', 
            minute: '2-digit',
            hour12: false 
          });
          
          const endTime = event.end ? event.end.toLocaleTimeString('es-ES', { 
            hour: '2-digit', 
            minute: '2-digit',
            hour12: false 
          }) : 'Fin no definido';
          
          const duracion = event.end ? 
            Math.round((event.end - event.start) / (1000 * 60)) + ' min' : 
            'Duración no definida';
          
          const tooltipContent = `
            <strong>Cliente:</strong> ${event.extendedProps.cliente}<br>
            <strong>Especialista:</strong> ${event.extendedProps.especialista}<br>
            <strong>Servicios:</strong> ${event.extendedProps.servicios}<br>
            <strong>Horario:</strong> ${startTime} - ${endTime}<br>
            <strong>Duración:</strong> ${duracion}
          `;
          
          info.el.setAttribute('title', tooltipContent.replace(/<br>/g, '\n'));
        }
      });
      
      calendar.render();
    }

    // `id` es el id del EVENTO de FullCalendar (para eventos con varios
    // especialistas viene sufijado, `${turnoIdReal}_${especialistaId}`,
    // para que cada especialista tenga su propio bloque visual). `turnoIdReal`
    // es el id real del documento en `turnos` — nunca hay que derivarlo
    // recortando `id` (los turnos nuevos usan IDs determinísticos con
    // varios guiones bajos, `negocioId_userId_fecha_horario`, así que
    // "cortar en el primer guion bajo" da cualquier cosa menos el id real).
    function crearEventoTurno(id, data, clienteNombre, serviciosNombres, especialistaId, horarioInicio, horarioFin, esMultiplesEspecialistas = false, turnoIdReal = id) {
      const especialistaNombre = obtenerNombreEspecialista(especialistaId);
      const titulo = esMultiplesEspecialistas 
        ? `${clienteNombre} - ${especialistaNombre}`
        : `${clienteNombre} - ${especialistaNombre}`;
      
      // Asegurar que horarioFin sea posterior a horarioInicio
      let horaFinCalculada = horarioFin;
      if (horarioInicio === horarioFin) {
        // Si no hay horarioFin, calcularlo basado en la duración
        let duracion = 30; // Default 30 minutos
        
        // Buscar duración en serviciosPorEspecialista
        if (data.serviciosPorEspecialista && data.serviciosPorEspecialista[especialistaId]) {
          const servicios = data.serviciosPorEspecialista[especialistaId];
          duracion = servicios.reduce((total, servicio) => total + (servicio.duracion || 30), 0);
        } else if (data.duracionTotal && data.especialistaIds && data.especialistaIds.length > 0) {
          // Dividir la duración total entre especialistas como fallback
          duracion = Math.round(data.duracionTotal / data.especialistaIds.length);
        }
        
        // Calcular horarioFin
        const [hora, minuto] = horarioInicio.split(':').map(Number);
        const inicioMinutos = hora * 60 + minuto;
        const finMinutos = inicioMinutos + duracion;
        const horaFin = Math.floor(finMinutos / 60).toString().padStart(2, '0');
        const minutoFin = (finMinutos % 60).toString().padStart(2, '0');
        horaFinCalculada = `${horaFin}:${minutoFin}`;
      }
      
      // ✅ NUEVO: Generar un color único basado en el ID del turno padre para eventos múltiples
      const turnoBaseId = esMultiplesEspecialistas ? turnoIdReal : null;
      const colorBordeGrupo = turnoBaseId ? generarColorDesdeId(turnoBaseId) : null;
      
      return {
        id: id,
        title: titulo,
        start: `${data.fecha}T${horarioInicio}`,
        end: `${data.fecha}T${horaFinCalculada}`,
        allDay: false,
        extendedProps: {
          turnoId: turnoIdReal,
          cliente: clienteNombre,
          telefono: data.cliente?.telefono || 'No especificado',
          email: data.cliente?.email || 'No especificado',
          servicios: serviciosNombres,
          especialista: especialistaNombre,
          especialistaId: especialistaId,
          todosLosEspecialistas: data.especialistaIds ? data.especialistaIds.map(id => obtenerNombreEspecialista(id)).join(', ') : especialistaNombre,
          observaciones: data.observaciones || 'Sin observaciones',
          estado: data.estado || 'pendiente',
          esMultiplesEspecialistas: esMultiplesEspecialistas,
          horarioInicio: horarioInicio,
          horarioFin: horaFinCalculada,
          duracion: calcularDuracionEnMinutos(horarioInicio, horaFinCalculada),
          // ✅ NUEVO: Guardar el ID base para agrupamiento visual
          turnoBaseId: turnoBaseId,
          colorBordeGrupo: colorBordeGrupo
        },
        className: `fc-event-${data.estado || 'pendiente'} ${esMultiplesEspecialistas ? 'fc-event-grupo-multiple' : ''}`,
        borderColor: esMultiplesEspecialistas ? colorBordeGrupo : 'transparent',
        backgroundColor: getEventColorBySpecialist(especialistaId),
        textColor: '#ffffff'
      };
    }

    function generarColorDesdeId(id) {
      // Colores distintivos para bordes de grupos
      const coloresGrupo = [
        '#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', '#FFEAA7',
        '#DDA0DD', '#98D8C8', '#F7DC6F', '#BB8FCE', '#85C1E9',
        '#F8C471', '#82E0AA', '#F1948A', '#D7BDE2', '#A3E4D7'
      ];
      
      // Generar índice basado en el ID
      let hash = 0;
      for (let i = 0; i < id.length; i++) {
        hash = id.charCodeAt(i) + ((hash << 5) - hash);
      }
      const index = Math.abs(hash) % coloresGrupo.length;
      
      return coloresGrupo[index];
    }

    function getEventColorBySpecialist(especialistaId) {
      // Mapa de colores fijos para especialistas conocidos
      const coloresFijos = {
        'esp_analia_solange': '#b285bfff',
        'esp_agustin_matias': '#aaaad3ff',
        'esp_blondie_flores': '#95bec3ff',
        'esp_monica_flores': '#92bc8bff',
        // Agregar más especialistas según necesites
      };
      
      // Si tenemos un color fijo para este especialista, usarlo
      if (coloresFijos[especialistaId]) {
        return coloresFijos[especialistaId];
      }
      
      // Para especialistas no mapeados, usar colores de respaldo
      const coloresRespaldo = [
        '#96CEB4', '#FFEAA7', '#DDA0DD', '#98D8C8', '#F7DC6F',
        '#BB8FCE', '#85C1E9', '#F8C471', '#82E0AA', '#F1948A',
        '#D7BDE2', '#A3E4D7', '#F9E79F', '#D2B4DE', '#A9CCE3'
      ];
      
      // Generar índice basado en el ID del especialista
      let hash = 0;
      for (let i = 0; i < especialistaId.length; i++) {
        hash = especialistaId.charCodeAt(i) + ((hash << 5) - hash);
      }
      const index = Math.abs(hash) % coloresRespaldo.length;
      
      return coloresRespaldo[index];
    }


    function calcularDuracionEnMinutos(horarioInicio, horarioFin) {
      const [horaInicio, minutoInicio] = horarioInicio.split(':').map(Number);
      const [horaFin, minutoFin] = horarioFin.split(':').map(Number);
      
      const inicioMinutos = horaInicio * 60 + minutoInicio;
      const finMinutos = horaFin * 60 + minutoFin;
      
      return finMinutos - inicioMinutos;
    }

    async function recargarVistaCalendario() {
      if (!calendar) return;
      
      try {
        
        // Obtener información de la vista actual
        const vistaActual = calendar.view;
        const tipoVista = vistaActual.type;
        const fechaActual = vistaActual.currentStart;
        
        
        // Método 1: Forzar recarga cambiando temporalmente la vista
        // Esto es más efectivo que refetchEvents() solo
        if (tipoVista === 'timeGridWeek' || tipoVista === 'timeGridDay') {
          // Para vistas semanales y diarias, cambiar temporalmente a month y volver
          calendar.changeView('dayGridMonth', fechaActual);
          setTimeout(() => {
            calendar.changeView(tipoVista, fechaActual);
          }, 100);
        } else {
          // Para vista mensual, recargar directamente
          calendar.refetchEvents();
        }
        
      } catch (error) {
        console.error('❌ Error recargando vista calendario:', error);
        // Fallback: recarga básica
        if (calendar) {
          calendar.refetchEvents();
        }
      }
    }

    // cliente/observaciones ya no viven en el documento del turno (ver
    // firestore.rules y guardarTurno en firestore.js) — quedan en
    // turnos/{id}/privado/datos, con lectura restringida al dueño del
    // turno o al admin/superadmin de ese negocio. El panel admin SIEMPRE
    // los necesita (calendario, lista del día, modal de detalle), así que
    // estos dos helpers los traen y los mezclan de vuelta en el objeto
    // del turno — el resto del código sigue leyendo turno.cliente /
    // turno.observaciones exactamente igual que antes.
    // Devuelve null (no un objeto vacío) cuando no hay subdocumento — así
    // el merge de quien llama (`{...doc.data(), ...(privado || {})}`) no
    // pisa con valores vacíos el cliente/observaciones de un turno viejo,
    // de antes de este cambio, que todavía los tiene guardados directo en
    // el documento principal (nunca se migraron, y no hace falta: alcanza
    // con no pisarlos).
    async function obtenerDatosPrivadosTurno(turnoId) {
      try {
        const doc = await db.collection('turnos').doc(turnoId).collection('privado').doc('datos').get();
        return doc.exists ? doc.data() : null;
      } catch (error) {
        console.error('Error obteniendo datos privados del turno:', turnoId, error);
        return null;
      }
    }

    async function obtenerDatosPrivadosTurnos(turnoIds) {
      const entradas = await Promise.all(
        turnoIds.map(async (id) => [id, await obtenerDatosPrivadosTurno(id)])
      );
      return Object.fromEntries(entradas);
    }

    async function loadTurnosForDate(date) {
      try {
        
        // Corregir formato de fecha para el título
        const fechaObj = new Date(date);
        const fechaAjustada = new Date(fechaObj.getTime() + fechaObj.getTimezoneOffset() * 60000);
        
        const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
        elements.fechaTitulo.textContent = `Turnos para ${fechaAjustada.toLocaleDateString('es-AR', options)}`;
        
        const snapshot = await db.collection('turnos')
          .where('negocioId', '==', obtenerNegocioIdActual())
          .where('fecha', '==', date)
          .orderBy('horario', 'asc')
          .get();

        const privadosPorId = await obtenerDatosPrivadosTurnos(snapshot.docs.map(doc => doc.id));
        renderTurnos(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data(), ...(privadosPorId[doc.id] || {}) })));
        
      } catch (error) {
        console.error("❌ Error cargando turnos:", error);
        elements.turnosList.innerHTML = '<p>Error al cargar los turnos. Intente nuevamente.</p>';
      }
    }

    function renderTurnos(turnos) {
      if (!elements.turnosList) return;
      
      if (turnos.length === 0) {
        elements.turnosList.innerHTML = '<p class="sin-turnos">No hay turnos para esta fecha.</p>';
        return;
      }
      
      elements.turnosList.innerHTML = turnos.map(turno => {
        const especialistaIds = turno.especialistaIds || [];
        const nombresEspecialistas = especialistaIds.map(id => obtenerNombreEspecialista(id)).join(', ');
        
        // Obtener servicios específicos por especialista
        let serviciosInfo = obtenerNombresServicios(turno.serviciosIds);
        if (turno.serviciosPorEspecialista) {
          serviciosInfo = '';
          Object.keys(turno.serviciosPorEspecialista).forEach(espId => {
            const servicios = turno.serviciosPorEspecialista[espId];
            const nombreEsp = obtenerNombreEspecialista(espId);
            const nombresServicios = servicios.map(s => s.nombre).join(', ');
            serviciosInfo += `<strong>${nombreEsp}:</strong> ${nombresServicios}<br>`;
          });
        }
        
        // Obtener horarios por especialista
        let horariosInfo = turno.horarioInicio || 'No especificado';
        if (turno.slotsPorEspecialista) {
          horariosInfo = '';
          Object.keys(turno.slotsPorEspecialista).forEach(espId => {
            const slots = turno.slotsPorEspecialista[espId];
            const nombreEsp = obtenerNombreEspecialista(espId);
            if (slots.length > 0) {
              horariosInfo += `<strong>${nombreEsp}:</strong> ${slots[0]}<br>`;
            }
          });
        }
        
        return `
        <div class="turno-card" data-id="${turno.id}">
          <div class="turno-header" data-id="${turno.id}">
            <div class="turno-sumario">
              <span class="turno-horario">${turno.horarioInicio}</span>
              <span class="turno-cliente">${escaparHtml(turno.cliente.nombre)}</span>
              <span class="turno-especialista">${nombresEspecialistas}</span>
              <span class="turno-estado ${formatearEstadoTurno(turno.estado).clase}">${formatearEstadoTurno(turno.estado).texto}</span>
            </div>
            <span class="toggle-icon">▼</span>
          </div>
          <div class="turno-detalles">
            <div class="turno-info">
              <p><strong>Servicios por especialista:</strong><br>${serviciosInfo}</p>
              <p><strong>Especialistas:</strong> ${nombresEspecialistas}</p>
              <p><strong>Horarios:</strong><br>${horariosInfo}</p>
              <p><strong>Teléfono:</strong> ${escaparHtml(turno.cliente.telefono)}</p>
              <p><strong>Email:</strong> ${escaparHtml(turno.cliente.email)}</p>
              ${turno.duracionTotal ? `<p><strong>Duración total:</strong> ${turno.duracionTotal} minutos</p>` : ''}
              ${turno.montoTotal ? `<p><strong>Monto total:</strong> $${turno.montoTotal}</p>` : ''}
              ${turno.observaciones ? `<p><strong>Observaciones:</strong> ${escaparHtml(turno.observaciones)}</p>` : ''}
            </div>
            <div class="turno-actions">
              <button class="btn-editar" data-id="${turno.id}">Editar</button>
              <button class="btn-eliminar-lista" data-id="${turno.id}">Eliminar</button>
            </div>
          </div>
        </div>
        `;
      }).join('');
      
      // El resto del código de event listeners se mantiene igual...
      document.querySelectorAll('.turno-header').forEach(header => {
        header.addEventListener('click', function(e) {
          if (e.target.tagName === 'BUTTON') return;
          
          const card = this.closest('.turno-card');
          const detalles = card.querySelector('.turno-detalles');
          const icon = this.querySelector('.toggle-icon');
          
          card.classList.toggle('expanded');
          detalles.style.display = card.classList.contains('expanded') ? 'block' : 'none';
          icon.textContent = card.classList.contains('expanded') ? '▲' : '▼';
        });
      });
      
      // Configurar eventos para los botones eliminar
      document.querySelectorAll('.btn-eliminar-lista').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          e.stopPropagation();
          const turnoId = e.currentTarget.getAttribute('data-id');
          
          if (confirm('¿Estás seguro de eliminar este turno?')) {
            const loading = mostrarLoading();
            try {
              await eliminarTurno(turnoId);
              const fechaActual = formatearFechaLocal(obtenerAhoraArgentina());
              await loadTurnosForDate(fechaActual);
            } catch (error) {
              console.error("Error eliminando desde lista:", error);
              alert("Error al eliminar el turno");
            } finally {
              loading.remove();
            }
          }
        });
      });
      
      // Configurar eventos para los botones editar
      document.querySelectorAll('.btn-editar').forEach(btn => {
        btn.addEventListener('click', async (e) => {
          e.stopPropagation();
          const turnoId = e.currentTarget.getAttribute('data-id');
          await abrirModalEdicionPorId(turnoId);
        });
      });
    }

    // Wrapper fino: el clic en un evento del calendario solo trae el
    // turnoId (extendedProps) — todo el armado real del modal (incluida
    // la conexión del botón "Eliminar") vive en abrirModalEdicionPorId,
    // que es la misma función que usa la vista de lista del día. Antes
    // había dos versiones separadas del mismo HTML (con los mismos
    // iconos SVG repetidos) que había que mantener sincronizadas a mano
    // — una de ellas nunca llegó a mostrar el estado del turno hasta que
    // se detectó acá.
    async function abrirModalEdicion(event) {
      const turnoId = event.extendedProps.turnoId;
      if (!turnoId) {
        console.error('Evento de calendario sin turnoId en extendedProps');
        alert('Error al cargar los datos del turno');
        return;
      }
      await abrirModalEdicionPorId(turnoId);
    }

    async function abrirModalEdicionPorId(turnoId) {
      try {
        const config = await obtenerConfiguracion();
        await generarOpcionesHorario(config);
        
        const doc = await db.collection('turnos').doc(turnoId).get();
        if (!doc.exists) {
          alert('Turno no encontrado');
          return;
        }

        const datosPrivados = await obtenerDatosPrivadosTurno(turnoId);
        const turno = { ...doc.data(), ...(datosPrivados || {}) };
        currentTurnoId = turnoId;
        
        // #turno-info p usa display:flex (para alinear "Label: valor" en
        // una sola línea) — un <br> adentro de un <p> flex NO corta línea,
        // quedaba todo amontonado en una fila. Por eso cada línea (una por
        // especialista) se arma como su PROPIO <p>, nunca con <br> adentro
        // de uno solo.
        //
        // El nombre del especialista se muestra siempre junto al servicio
        // y al horario que le corresponde (aunque haya uno solo) — es el
        // dato que identifica quién hace el trabajo. Lo que se evita es la
        // sección aparte "Especialistas" que había antes, que repetía esos
        // mismos nombres una tercera vez sin aportar nada nuevo.
        function formatearInfoPorEspecialista(entradas, etiqueta, formatearValor) {
          if (entradas.length === 0) {
            return `<p><strong>${etiqueta}:</strong> No especificado</p>`;
          }
          const filas = entradas
            .map(([espId, valor]) => `<p class="turno-info-detalle"><strong>${obtenerNombreEspecialista(espId)}:</strong> ${formatearValor(valor)}</p>`)
            .join('');
          return `<p><strong>${etiqueta}:</strong></p>${filas}`;
        }

        const entradasServicios = turno.serviciosPorEspecialista
          ? Object.entries(turno.serviciosPorEspecialista)
          : [];
        const serviciosInfo = entradasServicios.length > 0
          ? formatearInfoPorEspecialista(entradasServicios, 'Servicios', (servicios) => servicios.map(s => s.nombre).join(', '))
          : `<p><strong>Servicios:</strong> ${obtenerNombresServicios(turno.serviciosIds)}</p>`;

        const entradasHorarios = turno.slotsPorEspecialista
          ? Object.entries(turno.slotsPorEspecialista)
              .filter(([, slots]) => slots.length > 0)
              .map(([espId, slots]) => {
                const horarioInicio = slots[0];
                const duracion = turno.serviciosPorEspecialista?.[espId]
                  ?.reduce((total, servicio) => total + servicio.duracion, 0) || 30;

                const [hora, minuto] = horarioInicio.split(':').map(Number);
                const finMinutos = hora * 60 + minuto + duracion;
                const horaFin = Math.floor(finMinutos / 60).toString().padStart(2, '0');
                const minutoFin = (finMinutos % 60).toString().padStart(2, '0');

                return [espId, `${horarioInicio} - ${horaFin}:${minutoFin}`];
              })
          : [];
        const horariosInfo = entradasHorarios.length > 0
          ? formatearInfoPorEspecialista(entradasHorarios, 'Horarios', (valor) => valor)
          : `<p><strong>Horarios:</strong> ${turno.horarioInicio || 'No especificado'}</p>`;

        document.getElementById('turno-id').value = turnoId;
        document.getElementById('edit-fecha').value = turno.fecha;
        document.getElementById('edit-horario').value = turno.horario || turno.horarioInicio;

        // Mostrar información completa del turno
        document.getElementById('turno-info').innerHTML = `
          <p><strong>Cliente:</strong> ${escaparHtml(turno.cliente.nombre)}</p>
          ${serviciosInfo}
          ${horariosInfo}
          <p><strong>Teléfono:</strong> ${escaparHtml(turno.cliente.telefono)}</p>
          <p><strong>Estado:</strong> ${formatearEstadoTurno(turno.estado).texto}</p>
          ${turno.duracionTotal ? `<p><strong>Duración total:</strong> ${turno.duracionTotal} minutos</p>` : ''}
          ${turno.montoTotal ? `<p><strong>Monto total:</strong> $${turno.montoTotal}</p>` : ''}
          ${turno.señaAbonada ? `<p><strong>Seña abonada:</strong> $${turno.señaAbonada}</p>` : ''}
        `;

        // El botón "Eliminar" del modal ya está conectado una sola vez,
        // en el arranque, por setupModalEvents() — usa currentTurnoId
        // (seteado arriba), así que no hace falta volver a conectarlo acá
        // cada vez que se abre el modal (antes se hacía dos veces: acá y
        // en setupModalEvents, lo que disparaba el eliminado dos veces).
        elements.modalEditar.style.display = 'block';
      } catch (error) {
        console.error("Error abriendo modal de edición:", error);
        alert("Error al cargar los datos del turno");
      }
    }


    async function generarOpcionesHorario(config) {
      const selectHorario = document.getElementById('edit-horario');
      selectHorario.innerHTML = '';
      
      // Convertir horarios de apertura/cierre a minutos
      const [aperturaH, aperturaM] = config.horarioApertura.split(':').map(Number);
      const [cierreH, cierreM] = config.horarioCierre.split(':').map(Number);
      
      let horaActual = aperturaH;
      let minutoActual = aperturaM;
      
      while (horaActual < cierreH || (horaActual === cierreH && minutoActual < cierreM)) {
        const horaStr = horaActual.toString().padStart(2, '0');
        const minutoStr = minutoActual.toString().padStart(2, '0');
        const option = document.createElement('option');
        option.value = `${horaStr}:${minutoStr}`;
        option.textContent = `${horaStr}:${minutoStr}`;
        selectHorario.appendChild(option);
        
        // Avanzar el tiempo
        minutoActual += config.duracionTurno;
        if (minutoActual >= 60) {
          horaActual += Math.floor(minutoActual / 60);
          minutoActual = minutoActual % 60;
        }
      }
    }

    async function verificarDisponibilidad(fecha, horario, turnoId = null) {
      try {
        const config = await obtenerConfiguracion();
        
        // Convertir horario a minutos
        const [hora, minuto] = horario.split(':').map(Number);
        const inicioEnMinutos = hora * 60 + minuto;
        const finEnMinutos = inicioEnMinutos + config.duracionTurno;
        
        // Consultar todos los turnos para la fecha
        const snapshot = await db.collection('turnos')
          .where('negocioId', '==', obtenerNegocioIdActual())
          .where('fecha', '==', fecha)
          .get();
        
        // Filtrar localmente los turnos que se solapan
        const turnosSolapados = snapshot.docs.filter(doc => {
          // Si estamos editando, excluir el turno actual
          if (turnoId && doc.id === turnoId) return false;
          
          const turno = doc.data();
          const turnoHorario = turno.horario || turno.horarioInicio;
          
          if (!turnoHorario) return false;
          
          const [turnoHora, turnoMinuto] = turnoHorario.split(':').map(Number);
          const turnoInicio = turnoHora * 60 + turnoMinuto;
          const turnoFin = turnoInicio + (turno.duracionTotal || config.duracionTurno);
          
          // Verificar solapamiento
          return (inicioEnMinutos < turnoFin && finEnMinutos > turnoInicio);
        });
        
        return {
          disponible: turnosSolapados.length === 0,
          mensaje: turnosSolapados.length > 0 ? 
            `El horario se solapa con ${turnosSolapados.length} turno(s) existente(s)` : 
            null
        };
      } catch (error) {
        console.error("Error verificando disponibilidad:", error);
        return {
          disponible: false,
          mensaje: "Error al verificar disponibilidad: " + error.message
        };
      }
    }

    async function verificarDisponibilidadCompletaEspecialista(especialistaId, fecha, horarioInicio, duracionTotal, turnoIdExcluir = null) {
      try {
        
        // 1. Verificar si el especialista existe y está activo
        const especialistaDoc = await db.collection('especialistas').doc(especialistaId).get();
        if (!especialistaDoc.exists) {
          return { disponible: false, mensaje: 'Especialista no encontrado' };
        }
        
        const especialista = especialistaDoc.data();
        if (!especialista.activo) {
          return { disponible: false, mensaje: 'El especialista no está activo' };
        }
        
        // 2. Verificar día laboral del especialista (CORREGIDO)
        const [year, month, day] = fecha.split('-').map(Number);
        const fechaObj = new Date(year, month - 1, day);
        const diaSemana = fechaObj.getDay(); // 0=Domingo, 1=Lunes, ..., 6=Sábado
        const dias = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
        const diaKey = dias[diaSemana];
        
        const horarioDia = especialista.horarioLaboral?.[diaKey];
        if (!horarioDia || !horarioDia.activo) {
          const nombreEspecialista = obtenerNombreEspecialista(especialistaId);
          const diasNombres = ['Domingos', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábados'];
          return {
            disponible: false,
            mensaje: `${nombreEspecialista} no trabaja los ${diasNombres[diaSemana]}`
          };
        }

        // 2.b Verificar bloqueos/ausencias (vacaciones, licencias, etc.).
        // Esta validación existía del lado del cliente (app.js) pero no
        // acá — permitía asignar un turno manualmente desde el admin a un
        // especialista que tiene cargada una ausencia ese día.
        const tieneBloqueo = await firestoreDB.verificarBloqueosEspecialista(especialistaId, fecha);
        if (tieneBloqueo) {
          const nombreEspecialista = obtenerNombreEspecialista(especialistaId);
          return {
            disponible: false,
            mensaje: `${nombreEspecialista} tiene una ausencia cargada ese día`
          };
        }

        // 3. Verificar horario dentro de la jornada laboral (resto del código igual)
        const [horaInicio, minutoInicio] = horarioInicio.split(':').map(Number);
        const inicioMinutos = horaInicio * 60 + minutoInicio;
        const finMinutos = inicioMinutos + duracionTotal;
        
        const [horaApertura, minutoApertura] = horarioDia.inicio.split(':').map(Number);
        const [horaCierre, minutoCierre] = horarioDia.fin.split(':').map(Number);
        const aperturaMinutos = horaApertura * 60 + minutoApertura;
        const cierreMinutos = horaCierre * 60 + minutoCierre;
        
        if (inicioMinutos < aperturaMinutos) {
          return { 
            disponible: false, 
            mensaje: `El horario ${horarioInicio} es antes de la apertura (${horarioDia.inicio})` 
          };
        }
        
        if (finMinutos > cierreMinutos) {
          return { 
            disponible: false, 
            mensaje: `El turno termina después del cierre (${horarioDia.fin})` 
          };
        }
        
        // 4. Verificar conflictos con otros turnos (resto del código igual)
        const snapshot = await db.collection('turnos')
          .where('negocioId', '==', obtenerNegocioIdActual())
          .where('fecha', '==', fecha)
          .where('especialistaIds', 'array-contains', especialistaId)
          .get();
        
        const turnosConflictivos = snapshot.docs.filter(doc => {
          if (turnoIdExcluir && doc.id === turnoIdExcluir) return false;
          
          const turnoExistente = doc.data();
          const turnoHorario = turnoExistente.horarioInicio || turnoExistente.horario;
          
          if (!turnoHorario) return false;
          
          const [existenteHora, existenteMinuto] = turnoHorario.split(':').map(Number);
          const existenteInicio = existenteHora * 60 + existenteMinuto;
          const existenteFin = existenteInicio + (turnoExistente.duracionTotal || 30);
          
          // Verificar solapamiento
          const haySolapamiento = (inicioMinutos < existenteFin && finMinutos > existenteInicio);
          
          if (haySolapamiento) {
          }
          
          return haySolapamiento;
        });
        
        if (turnosConflictivos.length > 0) {
          const nombreEspecialista = obtenerNombreEspecialista(especialistaId);
          return {
            disponible: false,
            mensaje: `${nombreEspecialista} tiene ${turnosConflictivos.length} turno(s) conflictivo(s) en ese horario`
          };
        }
        
        return { disponible: true, mensaje: null };
        
      } catch (error) {
        console.error("Error en verificación completa especialista:", error);
        return {
          disponible: false,
          mensaje: "Error al verificar disponibilidad del especialista"
        };
      }
    }

    async function verificarDisponibilidadCompleta(nuevoTurno, turnoActual, turnoIdExcluir) {
      try {
        // Verificar disponibilidad para cada especialista
        if (nuevoTurno.slotsPorEspecialista) {
          for (const [especialistaId, slots] of Object.entries(nuevoTurno.slotsPorEspecialista)) {
            if (slots.length === 0) continue;
            
            const primerSlot = slots[0];
            const duracionTotal = slots.length * 30; // 30 minutos por slot
            
            // Verificar disponibilidad completa del especialista
            const disponibilidad = await verificarDisponibilidadCompletaEspecialista(
              especialistaId, 
              nuevoTurno.fecha, 
              primerSlot, 
              duracionTotal, 
              turnoIdExcluir
            );
            
            if (!disponibilidad.disponible) {
              return disponibilidad;
            }
          }
        } else {
          // Para turnos con un solo especialista (compatibilidad con versiones anteriores)
          const especialistaId = turnoActual.especialistaId || (turnoActual.especialistaIds && turnoActual.especialistaIds[0]);
          if (especialistaId) {
            const duracionTotal = turnoActual.duracionTotal || 30;
            const disponibilidad = await verificarDisponibilidadCompletaEspecialista(
              especialistaId, 
              nuevoTurno.fecha, 
              nuevoTurno.horarioInicio, 
              duracionTotal, 
              turnoIdExcluir
            );
            
            if (!disponibilidad.disponible) {
              return disponibilidad;
            }
          }
        }
        
        return { disponible: true, mensaje: null };
        
      } catch (error) {
        console.error("Error en verificación completa:", error);
        return {
          disponible: false,
          mensaje: "Error al verificar disponibilidad: " + error.message
        };
      }
    }

    async function guardarCambiosTurno() {
      if (!currentTurnoId) {
        console.error('currentTurnoId no definido');
        return;
      }

      try {
        const user = firebase.auth().currentUser;
        if (!user) {
          alert('Debes iniciar sesión para realizar esta acción');
          return;
        }

        // Verificar si el usuario es administrador (dueño de este negocio)
        const isAdmin = await esEsteUsuarioOwnerDelNegocio(user.uid);

        if (!isAdmin) {
          alert('No tienes permisos de administrador para realizar esta acción');
          return;
        }

        const config = await obtenerConfiguracion();
        const nuevoHorario = document.getElementById('edit-horario').value;
        const nuevaFecha = document.getElementById('edit-fecha').value;
        
        // Validar horario
        const validacionHorario = validarHorario(nuevoHorario, config);
        if (!validacionHorario.valido) {
          alert(validacionHorario.mensaje);
          return;
        }
        
        // Crear fecha sin problemas de zona horaria
        const [year, month, day] = nuevaFecha.split('-').map(Number);
        const fechaObj = new Date(year, month - 1, day);
        
        // Obtener día de la semana (0=Domingo, 1=Lunes, ..., 6=Sábado)
        const diaSemana = fechaObj.getDay();
        const dias = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
        const diaKey = dias[diaSemana];
        
        // OBTENER EL TURNO ACTUAL PRIMERO
        const turnoDoc = await db.collection('turnos').doc(currentTurnoId).get();
        if (!turnoDoc.exists) {
          alert('El turno no existe');
          return;
        }

        const turnoActual = turnoDoc.data();

        // ✅ NUEVA VALIDACIÓN: VERIFICAR DISPONIBILIDAD POR ESPECIALISTA
        const especialistaIds = turnoActual.especialistaIds || [];
        
        if (especialistaIds.length > 0) {
          let algunEspecialistaDisponible = false;
          let mensajesError = [];
          
          for (const especialistaId of especialistaIds) {
            const especialista = especialistasMap[especialistaId];
            if (especialista && especialista.horarioLaboral) {
              const horarioDia = especialista.horarioLaboral[diaKey];
              
              if (horarioDia && horarioDia.activo) {
                algunEspecialistaDisponible = true;
                break; // Al menos uno trabaja, es suficiente
              } else {
                const nombreEspecialista = obtenerNombreEspecialista(especialistaId);
                mensajesError.push(`${nombreEspecialista} no trabaja los ${diaKey}s`);
              }
            }
          }
          
          if (!algunEspecialistaDisponible) {
            alert(`No se puede agendar el turno:\n${mensajesError.join('\n')}`);
            return;
          }
        } else {
          // ✅ VALIDACIÓN FALLBACK: Si no hay especialistas, usar configuración general
          // Pero primero ajustar el índice para coincidir con tu configuración
          // (Tu configuración usa 1=Lunes, 2=Martes, etc., mientras que getDay() usa 0=Domingo)
          const diaSemanaConfig = diaSemana === 0 ? 7 : diaSemana; // Ajustar domingo de 0 a 7
          
          if (!config.diasLaborales.includes(diaSemanaConfig)) {
            const diasNombres = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
            alert(`No se pueden agendar turnos los ${diasNombres[diaSemana]}s`);
            return;
          }
        }
        
        // CALCULAR EL DESPLAZAMIENTO TEMPORAL
        const [nuevaHora, nuevoMinuto] = nuevoHorario.split(':').map(Number);
        const [horaOriginal, minutoOriginal] = (turnoActual.horarioInicio || turnoActual.horario).split(':').map(Number);
        
        const desplazamientoMinutos = (nuevaHora * 60 + nuevoMinuto) - (horaOriginal * 60 + minutoOriginal);
        

        // PREPARAR ACTUALIZACIÓN
        const turnoActualizado = {
          fecha: nuevaFecha,
          horario: nuevoHorario,
          horarioInicio: nuevoHorario,
          actualizadoEl: firebase.firestore.FieldValue.serverTimestamp()
        };

        // MANEJAR ESPECIALISTAS MÚLTIPLES - CORREGIDO
        if (turnoActual.slotsPorEspecialista && Object.keys(turnoActual.slotsPorEspecialista).length > 1) {
          
          const nuevosSlotsPorEspecialista = {};
          const nuevosServiciosPorEspecialista = {};
          let todosLosSlots = [];
          let horarioInicioGlobal = null;
          let horarioFinGlobal = null;
          
          // Primero, encontrar el horario de inicio más temprano entre todos los especialistas
          Object.keys(turnoActual.slotsPorEspecialista).forEach(especialistaId => {
            const slots = turnoActual.slotsPorEspecialista[especialistaId];
            if (slots && slots.length > 0) {
              const primerSlot = slots[0];
              if (!horarioInicioGlobal || primerSlot < horarioInicioGlobal) {
                horarioInicioGlobal = primerSlot;
              }
            }
          });
          
          // Calcular el desplazamiento basado en el horario global
          const [horaInicioGlobal, minutoInicioGlobal] = horarioInicioGlobal.split(':').map(Number);
          const minutosInicioGlobal = horaInicioGlobal * 60 + minutoInicioGlobal;
          const minutosNuevoInicio = minutosInicioGlobal + desplazamientoMinutos;
          
          // Procesar cada especialista manteniendo la secuencia temporal RELATIVA
          Object.keys(turnoActual.slotsPorEspecialista).forEach(especialistaId => {
            const slotsOriginales = turnoActual.slotsPorEspecialista[especialistaId];
            
            if (slotsOriginales && slotsOriginales.length > 0) {
              // Calcular el desplazamiento relativo de este especialista
              const primerSlotOriginal = slotsOriginales[0];
              const [horaSlot, minutoSlot] = primerSlotOriginal.split(':').map(Number);
              const minutosSlotOriginal = horaSlot * 60 + minutoSlot;
              const desplazamientoRelativo = minutosSlotOriginal - minutosInicioGlobal;
              
              // Aplicar desplazamiento global + relativo
              const minutosNuevoSlot = minutosNuevoInicio + desplazamientoRelativo;
              const nuevaHoraSlot = Math.floor(minutosNuevoSlot / 60);
              const nuevoMinutoSlot = minutosNuevoSlot % 60;
              const nuevoPrimerSlot = `${nuevaHoraSlot.toString().padStart(2, '0')}:${nuevoMinutoSlot.toString().padStart(2, '0')}`;
              
              // Calcular todos los slots para este especialista
              const nuevosSlotsEspecialista = [];
              for (let i = 0; i < slotsOriginales.length; i++) {
                const slotMinutos = minutosNuevoSlot + (i * 30);
                const slotHora = Math.floor(slotMinutos / 60);
                const slotMinuto = slotMinutos % 60;
                const nuevoSlot = `${slotHora.toString().padStart(2, '0')}:${slotMinuto.toString().padStart(2, '0')}`;
                nuevosSlotsEspecialista.push(nuevoSlot);
                todosLosSlots.push(nuevoSlot);
                
                // Actualizar horario fin global
                const slotFinMinutos = slotMinutos + 30;
                if (!horarioFinGlobal || slotFinMinutos > horarioFinGlobal) {
                  horarioFinGlobal = slotFinMinutos;
                }
              }
              
              nuevosSlotsPorEspecialista[especialistaId] = nuevosSlotsEspecialista;
              
              // Preservar servicios por especialista
              if (turnoActual.serviciosPorEspecialista && turnoActual.serviciosPorEspecialista[especialistaId]) {
                nuevosServiciosPorEspecialista[especialistaId] = turnoActual.serviciosPorEspecialista[especialistaId];
              }
              
            }
          });
          
          // Calcular nuevo horario de fin
          const horaFinGlobal = Math.floor(horarioFinGlobal / 60);
          const minutoFinGlobal = horarioFinGlobal % 60;
          const nuevoHorarioFin = `${horaFinGlobal.toString().padStart(2, '0')}:${minutoFinGlobal.toString().padStart(2, '0')}`;
          
          // Eliminar duplicados y ordenar slots
          todosLosSlots = [...new Set(todosLosSlots)].sort();
          
          turnoActualizado.slotsPorEspecialista = nuevosSlotsPorEspecialista;
          turnoActualizado.slotsOcupados = todosLosSlots;
          turnoActualizado.horarioFin = nuevoHorarioFin;
          
          if (Object.keys(nuevosServiciosPorEspecialista).length > 0) {
            turnoActualizado.serviciosPorEspecialista = nuevosServiciosPorEspecialista;
          }
          
          
        } else {
          // COMPORTAMIENTO ORIGINAL PARA UN SOLO ESPECIALISTA
          const duracionTotal = turnoActual.duracionTotal || 30;
          
          // Convertir horario a minutos para calcular fin
          const [hora, minuto] = nuevoHorario.split(':').map(Number);
          const inicioMinutos = hora * 60 + minuto;
          const finMinutos = inicioMinutos + duracionTotal;
          const horaFin = Math.floor(finMinutos / 60).toString().padStart(2, '0');
          const minutoFin = (finMinutos % 60).toString().padStart(2, '0');
          const nuevoHorarioFin = `${horaFin}:${minutoFin}`;

          // Calcular nuevos slots ocupados
          const nuevosSlotsOcupados = [];
          for (let min = inicioMinutos; min < finMinutos; min += 30) {
            const horaSlot = Math.floor(min / 60);
            const minutoSlot = min % 60;
            nuevosSlotsOcupados.push(`${horaSlot.toString().padStart(2, '0')}:${minutoSlot.toString().padStart(2, '0')}`);
          }

          turnoActualizado.horarioFin = nuevoHorarioFin;
          turnoActualizado.slotsOcupados = nuevosSlotsOcupados;
          
          // Actualizar slots por especialista si existe
          if (turnoActual.slotsPorEspecialista) {
            const nuevosSlotsPorEspecialista = {};
            Object.keys(turnoActual.slotsPorEspecialista).forEach(especialistaId => {
              nuevosSlotsPorEspecialista[especialistaId] = nuevosSlotsOcupados;
            });
            turnoActualizado.slotsPorEspecialista = nuevosSlotsPorEspecialista;
          }
        }

        // VERIFICAR DISPONIBILIDAD COMPLETA (no por slots individuales)
        const disponibilidad = await verificarDisponibilidadCompleta(turnoActualizado, turnoActual, currentTurnoId);
        if (!disponibilidad.disponible) {
          alert(disponibilidad.mensaje);
          return;
        }

        
        // ACTUALIZAR EN FIRESTORE
        await db.collection('turnos').doc(currentTurnoId).update(turnoActualizado);
        
        // ACTUALIZAR VISTAS
        await loadTurnosForDate(nuevaFecha);

        if (calendar) {
          // ✅ SOLUCIÓN MEJORADA: Forzar recarga completa de la vista actual
          await recargarVistaCalendario();
        }
        
        if (calendar) {
          calendar.refetchEvents();
        }
        
        // Cerrar modal
        elements.modalEditar.style.display = 'none';
        
        mostrarMensajeExito('Turno actualizado correctamente');
        
      } catch (error) {
        console.error("❌ Error actualizando turno:", error);
        alert("Error al actualizar el turno: " + error.message);
      }
    }

    async function eliminarTurno(turnoId) {
      // Validación mejorada del ID
      if (!turnoId || typeof turnoId !== 'string') {
        console.error('ID de turno inválido:', turnoId);
        return false;
      }

      try {
        
        // Obtener la fecha del turno antes de eliminarlo
        const doc = await db.collection('turnos').doc(turnoId).get();
        if (!doc.exists) {
          alert('El turno ya no existe');
          return false;
        }
        
        const turnoData = doc.data();
        const fechaTurno = turnoData.fecha;

        // La cancelación (borrado + emails a cliente y negocio) pasa por
        // la Cloud Function cancelarTurno — deriva el rol de quien llama
        // (dueño del negocio / superadmin) del lado del servidor, en vez
        // de un .delete() directo desde acá.
        await firebase.functions().httpsCallable('cancelarTurno')({ turnoId });

        // Actualizar la vista del calendario
        if (calendar) {
          calendar.refetchEvents();
        }
        
        // Actualizar la lista de turnos
        await loadTurnosForDate(fechaTurno);
        
        // Cerrar modal si está abierto
        if (elements.modalEditar && elements.modalEditar.style.display === 'block') {
          elements.modalEditar.style.display = 'none';
        }
        
        // Mostrar mensaje de éxito
        mostrarMensajeExito('Turno eliminado correctamente');
        
        return true;
      } catch (error) {
        console.error('❌ Error al eliminar:', error);
        
        // Mensajes de error más específicos
        let mensajeError = 'Error al eliminar el turno';
        if (error.code === 'permission-denied') {
          mensajeError = 'No tienes permisos para eliminar turnos';
        } else if (error.code === 'not-found') {
          mensajeError = 'El turno ya no existe';
        }
        
        alert(mensajeError + ': ' + (error.message || 'Por favor intente nuevamente'));
        return false;
      }
    }

    function obtenerNombresServicios(serviciosIds) {
      if (!Array.isArray(serviciosIds) || serviciosIds.length === 0) {
        return 'Servicios no especificados';
      }
      
      const nombres = serviciosIds.map(servicioId => {
        const servicio = serviciosMap[servicioId];
        return servicio ? servicio.nombre : servicioId; // Si no encuentra, muestra el ID
      });
      
      return nombres.join(', ');
    }

    function setupModalEvents() {
      const modal = document.getElementById('modal-editar');
      const btnEliminar = document.getElementById('btn-eliminar-modal');
      
      if (btnEliminar) {
        // Limpiar eventos previos completamente
        btnEliminar.replaceWith(btnEliminar.cloneNode(true));
        const newBtnEliminar = document.getElementById('btn-eliminar-modal');
        
        newBtnEliminar.addEventListener('click', async (e) => {
          e.preventDefault();
          e.stopPropagation();
          
          
          if (!currentTurnoId) {
            console.error('❌ No hay turno seleccionado para eliminar');
            alert('No hay turno seleccionado para eliminar');
            return;
          }

          if (confirm('¿Estás seguro de eliminar este turno permanentemente? Esta acción no se puede deshacer.')) {
            
            const loadingIndicator = mostrarLoading();
            try {
              const success = await eliminarTurno(currentTurnoId);
              if (success) {
                // El modal se cierra dentro de eliminarTurno
              } else {
                console.error('❌ Eliminación falló');
              }
            } catch (error) {
              console.error('❌ Error en eliminación:', error);
            } finally {
              loadingIndicator.remove();
            }
          }
        });
      }
    }

