    // Cargar categorías en el select del modal
    async function cargarCategoriasEnSelect() {
        const select = document.getElementById('servicio-categoria');
        if (!select) {
            console.error('❌ No se encontró el select de categorías');
            return;
        }
        
        // Si ya tenemos categorías cargadas, usarlas
        if (Object.keys(categoriasMap).length > 0) {
            llenarSelectConCategorias(select);
            return;
        }
        
        // Si no hay categorías, cargarlas desde Firestore
        try {
            const categoriasSnapshot = await db.collection('categorias').where('negocioId', '==', obtenerNegocioIdActual()).orderBy('orden').get();
            
            categoriasMap = {};
            categoriasSnapshot.forEach(doc => {
                categoriasMap[doc.id] = { id: doc.id, ...doc.data() };
            });
            
            llenarSelectConCategorias(select);
            
        } catch (error) {
            console.error('❌ Error cargando categorías:', error);
            select.innerHTML = '<option value="">Error al cargar categorías</option>';
        }
    }

    // Función auxiliar para llenar el select
    function llenarSelectConCategorias(select) {
        select.innerHTML = '<option value="">Selecciona una categoría</option>';
        
        Object.values(categoriasMap)
            .sort((a, b) => (a.orden || 0) - (b.orden || 0))
            .forEach(categoria => {
                const option = document.createElement('option');
                option.value = categoria.id;
                option.textContent = categoria.nombre;
                select.appendChild(option);
            });
        
    }

