    // Guardar servicio (crear o actualizar)
    async function guardarServicio() {
        const loading = mostrarLoading();
        
        try {
            const servicioId = document.getElementById('servicio-id').value;
            const servicioData = {
                nombre: document.getElementById('servicio-nombre').value.trim(),
                categoriaId: document.getElementById('servicio-categoria').value,
                descripcion: document.getElementById('servicio-descripcion').value.trim(),
                duracion: parseInt(document.getElementById('servicio-duracion').value),
                precio: parseInt(document.getElementById('servicio-precio').value),
                activo: document.getElementById('servicio-activo').checked,
                promo: document.getElementById('servicio-promo').checked,
                descuentoPorcentaje: parseInt(document.getElementById('servicio-descuento-porcentaje').value, 10),
                actualizadoEl: firebase.firestore.FieldValue.serverTimestamp()
            };
            
            // Validaciones básicas
            if (!servicioData.nombre) {
                throw new Error('El nombre es obligatorio');
            }
            if (!servicioData.categoriaId) {
                throw new Error('La categoría es obligatoria');
            }
            if (isNaN(servicioData.duracion) || servicioData.duracion < 1) {
                throw new Error('La duración debe ser un número mayor a 0');
            }
            if (isNaN(servicioData.precio) || servicioData.precio < 0) {
                throw new Error('El precio debe ser un número no negativo');
            }
            
            if (servicioId) {
                // Actualizar servicio existente
                await db.collection('servicios').doc(servicioId).update(servicioData);
                mostrarMensajeExito('Servicio actualizado correctamente');
            } else {
                // Crear nuevo servicio CON ID PERSONALIZADO
                const nuevoId = generarIdServicio(servicioData.nombre);
                
                // Verificar que el ID no exista
                const idUnico = await verificarIdUnico('servicios', nuevoId);
                if (!idUnico) {
                    throw new Error(`Ya existe un servicio con un nombre similar. El ID "${nuevoId}" ya está en uso.`);
                }
                
                servicioData.creadoEl = firebase.firestore.FieldValue.serverTimestamp();
                servicioData.orden = Object.keys(serviciosMap).length + 1;
                servicioData.id = nuevoId; // También guardar el ID en los datos
                servicioData.negocioId = obtenerNegocioIdActual();
                
                await db.collection('servicios').doc(nuevoId).set(servicioData);
                mostrarMensajeExito('Servicio creado correctamente');
            }
            
            // Recargar servicios
            await cargarServiciosYMostrar();
            
            // Cerrar modal
            document.getElementById('modal-servicio').style.display = 'none';
            
        } catch (error) {
            console.error('❌ Error guardando servicio:', error);
            mostrarMensajeError(error.message || 'Error al guardar el servicio');
        } finally {
            loading.remove();
        }
    }

    // Eliminar servicio
    async function eliminarServicio(servicioId) {
        if (!servicioId) return;
        
        const servicio = serviciosMap[servicioId];
        if (!servicio) return;
        
        if (!confirm(`¿Estás seguro de eliminar el servicio "${servicio.nombre}"? Esta acción no se puede deshacer.`)) {
            return;
        }
        
        const loading = mostrarLoading();
        
        try {
            await db.collection('servicios').doc(servicioId).delete();
            mostrarMensajeExito('Servicio eliminado correctamente');
            
            // Recargar servicios
            await cargarServiciosYMostrar();
            
        } catch (error) {
            console.error('❌ Error eliminando servicio:', error);
            mostrarMensajeError('Error al eliminar el servicio');
        } finally {
            loading.remove();
        }
    }

    // Funciones de utilidad para servicios
    function formatearPrecio(precio) {
        // Formatear sin decimales y con separador de miles
        return new Intl.NumberFormat('es-AR', {
            minimumFractionDigits: 0,
            maximumFractionDigits: 0
        }).format(precio);
    }

    function formatearDuracionAdmin(minutos) {
        const horas = Math.floor(minutos / 60);
        const mins = minutos % 60;
        
        if (horas === 0) {
            // Menos de 1 hora: "30 min"
            return `${minutos} min`;
        } else if (mins === 0) {
            // Horas exactas: "1 hora", "2 horas"
            return `${horas} ${horas === 1 ? 'hora' : 'horas'}`;
        } else {
            // Horas y minutos: "1 h 30 m", "2 h 30 m"
            return `${horas} h ${mins} m`;
        }
    }

