    function configurarModalCategorias() {
        const modal = document.getElementById('modal-categorias');
        const form = document.getElementById('form-categoria');
        if (!modal || !form) return;

        const closeBtn = modal.querySelector('.close-modal');
        const inputId = document.getElementById('categoria-id');
        const inputNombre = document.getElementById('categoria-nombre');
        const btnGuardar = document.getElementById('btn-guardar-categoria');
        const btnCancelarEdicion = document.getElementById('btn-cancelar-edicion-categoria');

        function volverAModoCreacion() {
            form.reset();
            inputId.value = '';
            btnGuardar.textContent = 'Crear Categoría';
            btnCancelarEdicion.style.display = 'none';
        }

        function cerrarModal() {
            modal.style.display = 'none';
            volverAModoCreacion();
        }

        closeBtn.addEventListener('click', cerrarModal);

        window.addEventListener('click', (e) => {
            if (e.target === modal) cerrarModal();
        });

        btnCancelarEdicion.addEventListener('click', volverAModoCreacion);

        // Delegar clicks de editar/eliminar (la lista se regenera en cada carga)
        document.getElementById('categorias-list').addEventListener('click', async (e) => {
            const btnEditar = e.target.closest('.btn-editar-categoria');
            const btnEliminar = e.target.closest('.btn-eliminar-categoria');

            if (btnEditar) {
                inputId.value = btnEditar.dataset.id;
                inputNombre.value = btnEditar.dataset.nombre;
                btnGuardar.textContent = 'Guardar Cambios';
                btnCancelarEdicion.style.display = 'inline-flex';
                inputNombre.focus();
            }

            if (btnEliminar) {
                const categoriaId = btnEliminar.dataset.id;
                const categoriaNombre = btnEliminar.dataset.nombre;

                const enUso = await db.collection('servicios')
                    .where('negocioId', '==', obtenerNegocioIdActual())
                    .where('categoriaId', '==', categoriaId)
                    .limit(1)
                    .get();

                if (!enUso.empty) {
                    mostrarMensajeError(`No se puede eliminar "${categoriaNombre}": todavía tiene servicios cargados. Eliminá o reasigná esos servicios primero.`);
                    return;
                }

                const confirmar = await mostrarModalConfirmacion(`¿Eliminar la categoría "${categoriaNombre}"? Esta acción no se puede deshacer.`, 'Sí, eliminar categoría');
                if (!confirmar) return;

                try {
                    await db.collection('categorias').doc(categoriaId).delete();
                    mostrarMensajeExito('Categoría eliminada correctamente');
                    await cargarCategoriasParaGestion();
                    await cargarServiciosYMostrar();
                } catch (error) {
                    console.error('❌ Error eliminando categoría:', error);
                    mostrarMensajeError('Error al eliminar la categoría');
                }
            }
        });

        form.addEventListener('submit', async (e) => {
            e.preventDefault();

            const nombre = inputNombre.value.trim();
            if (!nombre) return;

            const categoriaId = inputId.value;

            try {
                if (categoriaId) {
                    await db.collection('categorias').doc(categoriaId).update({ nombre });
                    mostrarMensajeExito('Categoría actualizada correctamente');
                } else {
                    const nuevoId = `cat_${normalizarParaId(nombre)}`;

                    const esUnico = await verificarIdUnico('categorias', nuevoId);
                    if (!esUnico) {
                        mostrarMensajeError('Ya existe una categoría con un nombre muy similar.');
                        return;
                    }

                    const snapshot = await db.collection('categorias')
                        .where('negocioId', '==', obtenerNegocioIdActual())
                        .get();
                    const nuevoOrden = snapshot.size + 1;

                    await db.collection('categorias').doc(nuevoId).set({
                        negocioId: obtenerNegocioIdActual(),
                        nombre,
                        orden: nuevoOrden
                    });
                    mostrarMensajeExito('Categoría creada correctamente');
                }

                volverAModoCreacion();
                await cargarCategoriasParaGestion();
                await cargarServiciosYMostrar();
            } catch (error) {
                console.error('❌ Error guardando categoría:', error);
                mostrarMensajeError('Error al guardar la categoría');
            }
        });
    }

