    // Obtener días laborales formateados
    function obtenerDiasLaborales(horarioLaboral) {
        if (!horarioLaboral) return 'No definido';
        
        const dias = {
            lunes: 'L',
            martes: 'M',
            miercoles: 'M',
            jueves: 'J',
            viernes: 'V',
            sabado: 'S',
            domingo: 'D'
        };
        
        const diasActivos = [];
        
        for (const [dia, config] of Object.entries(horarioLaboral)) {
            if (config && config.activo) {
                diasActivos.push(dias[dia] || dia.charAt(0).toUpperCase());
            }
        }
        
        return diasActivos.join(' - ') || 'No definido';
    }

