        let html = '<div class="categorias-checkboxes-grid">';
        
        categoriasOrdenadas.forEach(categoria => {
            html += `
                <div class="checkbox-categoria-item">
                    <label class="checkbox-categoria-label">
                        <input type="checkbox" 
                              name="personal-categorias" 
                              value="${categoria.id}" 
                              class="checkbox-categoria">
                        <span class="checkbox-custom"></span>
                        <span class="checkbox-text">${categoria.nombre}</span>
                    </label>
                </div>
            `;
        });
        
        html += '</div>';
        contenedor.innerHTML = html;
        
