    // Abrir modal para crear/editar personal
    async function abrirModalPersonal(personalId = null) {
        const modal = document.getElementById('modal-personal');
        const titulo = document.getElementById('modal-personal-titulo');
        const form = document.getElementById('form-personal');
        const filePreview = document.getElementById('personal-foto-preview');
        const previewImg = document.getElementById('personal-foto-preview-img');
        // Ojo: ahora hay más de un .file-upload-label en la página (el del
        // logo de "Mi Negocio" y el de la foto de Personal) — hay que
        // buscarlo dentro de ESTE .file-upload-container, no con un
        // querySelector global que siempre agarra el primero del DOM.
        const uploadLabel = filePreview?.closest('.file-upload-container')?.querySelector('.file-upload-label');

        if (!modal || !titulo || !form) return;

        // Resetear formulario
        resetearFormularioPersonal();

        // Asegurar que las categorías estén cargadas en los checkboxes
        await cargarCategoriasCheckboxesPersonal();

        // Trae horarioApertura/horarioCierre del negocio a configNegocioParaPersonal
        // ANTES de armar el horario por defecto de un especialista nuevo — si no,
        // el default quedaba fijo en 09:00-20:00 sin importar el horario real del
        // negocio (ej. un negocio de 8 a 20 igual creaba especialistas de 9 a 20,
        // había que corregir cada día a mano).
        await aplicarRestriccionesNegocioAFormularioPersonal();

        if (personalId) {
            // Modo edición
            titulo.textContent = 'Editar Personal';
            document.getElementById('personal-id').value = personalId;
            
            const personal = personalMap[personalId];
            if (personal) {
                // Llenar campos básicos
                document.getElementById('personal-nombre').value = personal.nombre || '';
                document.getElementById('personal-telefono').value = personal.telefono || '';
                document.getElementById('personal-email').value = personal.email || '';
                document.getElementById('personal-activo').checked = personal.activo !== false;
                
                // Mostrar imagen existente si hay una
                if (personal.fotoUrl) {
                    previewImg.src = personal.fotoUrl;
                    filePreview.style.display = 'block';
                    uploadLabel.style.display = 'none';
                    document.getElementById('personal-foto-url').value = personal.fotoUrl;
                }
                
                // Establecer categorías
                if (personal.categoriasId) {
                    establecerCategoriasSeleccionadas(personal.categoriasId);
                }
                
                // Establecer horario laboral
                if (personal.horarioLaboral) {
                    establecerHorarioLaboral(personal.horarioLaboral);
                }
            }
        } else {
            // Modo creación
            titulo.textContent = 'Crear Personal';
            document.getElementById('personal-id').value = '';
            document.getElementById('personal-activo').checked = true;

            // Limpiar checkboxes
            const checkboxes = document.querySelectorAll('.checkbox-categoria');
            checkboxes.forEach(checkbox => {
                checkbox.checked = false;
            });
            
            // Establecer horario laboral por defecto — mismo horario que ya
            // tiene configurado el negocio (configNegocioParaPersonal, recién
            // cargado más arriba), no un valor fijo.
            const aperturaNegocio = configNegocioParaPersonal?.horarioApertura || '09:00';
            const cierreNegocio = configNegocioParaPersonal?.horarioCierre || '20:00';
            const horarioPorDefecto = {
                lunes: { inicio: aperturaNegocio, fin: cierreNegocio, activo: true },
                martes: { inicio: aperturaNegocio, fin: cierreNegocio, activo: true },
                miercoles: { inicio: aperturaNegocio, fin: cierreNegocio, activo: true },
                jueves: { inicio: aperturaNegocio, fin: cierreNegocio, activo: true },
                viernes: { inicio: aperturaNegocio, fin: cierreNegocio, activo: true },
                sabado: { inicio: aperturaNegocio, fin: cierreNegocio, activo: false },
                domingo: { inicio: aperturaNegocio, fin: cierreNegocio, activo: false }
            };
            establecerHorarioLaboral(horarioPorDefecto);

            // Re-aplicar las restricciones: establecerHorarioLaboral() recién
            // escribió valor y estado "activo" en los inputs, y esta llamada
            // anterior ya había corrido antes de eso — hay que repetirla para
            // que los días no laborales del negocio vuelvan a des-marcarse y
            // los inputs deshabilitados vuelvan a quedar así.
            await aplicarRestriccionesNegocioAFormularioPersonal();
        }

        modal.style.display = 'block';
    }

    async function aplicarRestriccionesNegocioAFormularioPersonal() {
        try {
            const negocioDoc = await db.collection('negocios').doc(obtenerNegocioIdActual()).get();
            if (!negocioDoc.exists) return;
            const negocio = negocioDoc.data();
            configNegocioParaPersonal = negocio;

            const diasLaboralesNegocio = normalizarDiasLaborales(negocio.diasLaborales);
            const horarioApertura = negocio.horarioApertura || '00:00';
            const horarioCierre = negocio.horarioCierre || '23:30';

            const dias = ['lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado', 'domingo'];
            dias.forEach((dia, index) => {
                const numeroDia = String(index + 1); // lunes=1 ... domingo=7
                const activoCheckbox = document.getElementById(`personal-${dia}-activo`);
                const inicioInput = document.getElementById(`personal-${dia}-inicio`);
                const finInput = document.getElementById(`personal-${dia}-fin`);
                if (!activoCheckbox || !inicioInput || !finInput) return;

                const esDiaLaboralDelNegocio = diasLaboralesNegocio.includes(numeroDia);

                activoCheckbox.disabled = !esDiaLaboralDelNegocio;
                if (!esDiaLaboralDelNegocio) {
                    activoCheckbox.checked = false;
                }

                inicioInput.min = horarioApertura;
                inicioInput.max = horarioCierre;
                finInput.min = horarioApertura;
                finInput.max = horarioCierre;
                inicioInput.disabled = !esDiaLaboralDelNegocio;
                finInput.disabled = !esDiaLaboralDelNegocio;

                const contenedorDia = activoCheckbox.closest('.dia-horario');
                if (contenedorDia) {
                    contenedorDia.classList.toggle('dia-no-laboral', !esDiaLaboralDelNegocio);
                }
            });
        } catch (error) {
            console.error('❌ Error aplicando restricciones del negocio al formulario de personal:', error);
        }
    }

    // Establecer horario laboral en el formulario
    function establecerHorarioLaboral(horarioLaboral) {
        const dias = ['lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado', 'domingo'];
        
        dias.forEach(dia => {
            const config = horarioLaboral[dia];
            const activoCheckbox = document.getElementById(`personal-${dia}-activo`);
            const inicioInput = document.getElementById(`personal-${dia}-inicio`);
            const finInput = document.getElementById(`personal-${dia}-fin`);
            
            if (activoCheckbox && inicioInput && finInput) {
                if (config && config.activo) {
                    activoCheckbox.checked = true;
                    inicioInput.value = config.inicio || '09:00';
                    finInput.value = config.fin || '18:00';
                } else {
                    activoCheckbox.checked = false;
                    inicioInput.value = '09:00';
                    finInput.value = '18:00';
                }
            }
        });
    }

    // Guardar personal (crear o actualizar)
    async function guardarPersonal() {
        const loading = mostrarLoading();
        
        try {
            const personalId = document.getElementById('personal-id').value;
            const fileInput = document.getElementById('personal-foto-file');
            const archivoImagen = fileInput.files[0];
            const fotoUrlExistente = document.getElementById('personal-foto-url').value;
            
            const personalData = {
                nombre: document.getElementById('personal-nombre').value.trim(),
                telefono: document.getElementById('personal-telefono').value.trim(),
                email: document.getElementById('personal-email').value.trim(),
                activo: document.getElementById('personal-activo').checked,
                categoriasId: obtenerCategoriasSeleccionadas(),
                horarioLaboral: obtenerHorarioLaboralFromForm(),
                actualizadoEl: firebase.firestore.FieldValue.serverTimestamp()
            };

            // Validaciones básicas
            if (!personalData.nombre) {
                throw new Error('El nombre es obligatorio');
            }

            // Los días/horarios de trabajo no pueden salirse de lo que el
            // negocio tiene configurado (por si alguien fuerza el campo
            // más allá de lo que permite el navegador).
            if (configNegocioParaPersonal) {
                const horarioApertura = configNegocioParaPersonal.horarioApertura || '00:00';
                const horarioCierre = configNegocioParaPersonal.horarioCierre || '23:30';
                const diasLaboralesNegocio = normalizarDiasLaborales(configNegocioParaPersonal.diasLaborales);
                const numerosDias = { lunes: '1', martes: '2', miercoles: '3', jueves: '4', viernes: '5', sabado: '6', domingo: '7' };

                for (const [dia, horario] of Object.entries(personalData.horarioLaboral)) {
                    if (!horario.activo) continue;
                    if (!diasLaboralesNegocio.includes(numerosDias[dia])) {
                        throw new Error(`El negocio no atiende los ${dia}s.`);
                    }
                    if (horario.inicio < horarioApertura || horario.fin > horarioCierre) {
                        throw new Error(`El horario de ${dia} debe estar entre ${horarioApertura} y ${horarioCierre}.`);
                    }
                }
            }

            let nuevoId = personalId;
            
            if (personalId) {
                // Modo edición - manejar imagen
                if (archivoImagen) {
                    // Subir nueva imagen
                    personalData.fotoUrl = await subirImagenPersonal(archivoImagen, personalId);
                } else if (fotoUrlExistente) {
                    // Mantener imagen existente
                    personalData.fotoUrl = fotoUrlExistente;
                } else {
                    // Eliminar imagen si no hay ninguna
                    personalData.fotoUrl = '';
                }
                
                await db.collection('especialistas').doc(personalId).update(personalData);
                mostrarMensajeExito('Personal actualizado correctamente');
                
            } else {
                // Modo creación
                nuevoId = generarIdPersonal(personalData.nombre);
                
                // Verificar que el ID no exista
                const idUnico = await verificarIdUnico('especialistas', nuevoId);
                if (!idUnico) {
                    throw new Error(`Ya existe un especialista con un nombre similar. El ID "${nuevoId}" ya está en uso.`);
                }
                
                // Subir imagen si se proporcionó
                if (archivoImagen) {
                    personalData.fotoUrl = await subirImagenPersonal(archivoImagen, nuevoId);
                } else {
                    personalData.fotoUrl = '';
                }
                
                personalData.creadoEl = firebase.firestore.FieldValue.serverTimestamp();
                personalData.orden = Object.keys(personalMap).length + 1;
                personalData.id = nuevoId;
                personalData.negocioId = obtenerNegocioIdActual();
                
                await db.collection('especialistas').doc(nuevoId).set(personalData);
                mostrarMensajeExito('Personal creado correctamente');
            }
            
            // Recargar personal
            await cargarPersonalYMostrar();

            // Actualizar el caché de especialistas del modal de turnos y la
            // vista del calendario, para que reflejen el cambio sin recargar
            // la página (nombre/foto/categorías nuevos, alta o baja).
            await recargarEspecialistasYVista();

            // Cerrar modal y resetear
            document.getElementById('modal-personal').style.display = 'none';
            resetearFormularioPersonal();
            
        } catch (error) {
            console.error('❌ Error guardando personal:', error);
            mostrarMensajeError(error.message || 'Error al guardar el personal');
        } finally {
            loading.remove();
        }
    }

    // Función para resetear el formulario de personal
    function resetearFormularioPersonal() {
        const form = document.getElementById('form-personal');
        const filePreview = document.getElementById('personal-foto-preview');
        const uploadLabel = filePreview?.closest('.file-upload-container')?.querySelector('.file-upload-label');

        form.reset();
        filePreview.style.display = 'none';
        uploadLabel.style.display = 'flex';
        document.getElementById('personal-foto-url').value = '';
    }

    // Obtener categorías seleccionadas en checkboxs
    //
    // Antes filtraba por `.checkbox-categoria:checked` a secas — pero los
    // checkboxes de días laborales (personal-lunes-activo, etc.) también
    // tienen esa clase (solo para el estilo visual compartido) y no tienen
    // `value`, así que cada checkbox de día activo colaba un "on" (el
    // value por defecto del navegador para un checkbox sin value) dentro
    // de categoriasId en cada guardado. Se acota por el `name` real de las
    // categorías, que solo tienen estos checkboxes.
    function obtenerCategoriasSeleccionadas() {
        const checkboxes = document.querySelectorAll('input[name="personal-categorias"]:checked');
        return Array.from(checkboxes).map(checkbox => checkbox.value);
    }

    // Establecer categorías seleccionadas al editar. Mismo acotamiento que
    // obtenerCategoriasSeleccionadas() — sin el name, esto también marca o
    // desmarca los checkboxes de días laborales (comparten la clase
    // .checkbox-categoria). Hoy queda inofensivo porque establecerHorario-
    // Laboral() se llama justo después y los vuelve a dejar bien, pero es
    // frágil depender de ese orden.
    function establecerCategoriasSeleccionadas(categoriasIds) {
        if (!categoriasIds || !Array.isArray(categoriasIds)) return;

        const checkboxes = document.querySelectorAll('input[name="personal-categorias"]');
        checkboxes.forEach(checkbox => {
            checkbox.checked = categoriasIds.includes(checkbox.value);
        });
    }

    // Obtener horario laboral desde el formulario
    function obtenerHorarioLaboralFromForm() {
        const dias = ['lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado', 'domingo'];
        const horarioLaboral = {};
        
        dias.forEach(dia => {
            const activoCheckbox = document.getElementById(`personal-${dia}-activo`);
            const inicioInput = document.getElementById(`personal-${dia}-inicio`);
            const finInput = document.getElementById(`personal-${dia}-fin`);
            
            if (activoCheckbox && inicioInput && finInput) {
                horarioLaboral[dia] = {
                    activo: activoCheckbox.checked,
                    inicio: inicioInput.value,
                    fin: finInput.value
                };
            }
        });
        
        return horarioLaboral;
    }

    // Eliminar personal (soft delete: establecer activo = false)
    async function eliminarPersonal(personalId) {
        if (!personalId) return;
        
        const personal = personalMap[personalId];
        if (!personal) return;
        
        if (!confirm(`¿Estás seguro de eliminar a "${personal.nombre}"? Esta acción no se puede deshacer.`)) {
            return;
        }
        
        const loading = mostrarLoading();
        
        try {
            // Soft delete: establecer activo = false
            await db.collection('especialistas').doc(personalId).update({
                activo: false,
                actualizadoEl: firebase.firestore.FieldValue.serverTimestamp()
            });
            
            mostrarMensajeExito('Personal eliminado correctamente');

            // Recargar personal
            await cargarPersonalYMostrar();

            // Igual que al guardar: refrescar caché de especialistas y calendario
            await recargarEspecialistasYVista();

        } catch (error) {
            console.error('❌ Error eliminando personal:', error);
            mostrarMensajeError('Error al eliminar el personal');
        } finally {
            loading.remove();
        }
    }

    // ============================================================
    // UTILIDADES: IDS Y STORAGE
    // ============================================================

    // Función para normalizar texto para IDs
    function normalizarParaId(texto) {
        return texto
            .toLowerCase()
            .normalize("NFD") // Separar acentos
            .replace(/[\u0300-\u036f]/g, "") // Eliminar acentos
            .replace(/[^a-z0-9]/g, "_") // Reemplazar caracteres no alfanuméricos con _
            .replace(/_+/g, "_") // Reemplazar múltiples _ por uno solo
            .replace(/^_|_$/g, ""); // Eliminar _ al inicio y final
    }

    // Generar ID para servicio
    function generarIdServicio(nombre) {
        return `serv_${normalizarParaId(nombre)}`;
    }

    // Generar ID para personal
    function generarIdPersonal(nombre) {
        return `esp_${normalizarParaId(nombre)}`;
    }

    // Verificar si un ID ya existe en una colección
    async function verificarIdUnico(coleccion, id) {
        try {
            const doc = await db.collection(coleccion).doc(id).get();
            return !doc.exists;
        } catch (error) {
            console.error(`Error verificando ID ${id}:`, error);
            return false;
        }
    }

    // Función para subir el logo/foto del negocio a Firebase Storage
    async function subirLogoNegocio(archivo, negocioId) {
        try {

            const extension = archivo.name.split('.').pop().toLowerCase();
            const nombreArchivo = `negocios/${negocioId}/logo_${Date.now()}.${extension}`;
            const storageRef = storage.ref().child(nombreArchivo);

            const snapshot = await storageRef.put(archivo);
            const downloadURL = await snapshot.ref.getDownloadURL();

            return downloadURL;

        } catch (error) {
            // Diagnóstico temporal: "storage/unauthorized" es el mismo error
            // genérico tanto si falla la auth como si el archivo no pasa las
            // reglas (tipo/tamaño) — sin esto no hay forma de saber cuál de
            // las dos fue con solo lo que ve el usuario en pantalla.
            console.error('❌ Error subiendo logo del negocio:', error, {
                uid: firebase.auth().currentUser?.uid,
                email: firebase.auth().currentUser?.email,
                archivoNombre: archivo?.name,
                archivoTipo: archivo?.type,
                archivoTamañoKB: archivo ? Math.round(archivo.size / 1024) : null
            });
            throw new Error('Error al subir la imagen: ' + error.message);
        }
    }

    // Función para subir imagen a Firebase Storage
    async function subirImagenPersonal(archivo, personalId) {
        try {

            // Crear referencia única en Storage — el negocioId va en el path
            // (igual que subirLogoNegocio) para que storage.rules pueda
            // verificar ownership por segmento de path; antes el archivo
            // vivía en "especialistas/{archivo}" sin ningún dato de a qué
            // negocio pertenecía, así que la regla no podía exigir más que
            // "estar logueado" — cualquier usuario autenticado podía
            // sobrescribir o borrar la foto de un especialista de OTRO negocio.
            const extension = archivo.name.split('.').pop().toLowerCase();
            const nombreArchivo = `especialistas/${obtenerNegocioIdActual()}/${personalId}_${Date.now()}.${extension}`;
            const storageRef = storage.ref().child(nombreArchivo);
            
            // Subir el archivo
            const snapshot = await storageRef.put(archivo);
            
            // Obtener URL de descarga
            const downloadURL = await snapshot.ref.getDownloadURL();
            
            return downloadURL;
            
        } catch (error) {
            console.error('❌ Error subiendo imagen:', error);
            throw new Error('Error al subir la imagen: ' + error.message);
        }
    }

    // Configurar el uploader de archivos
    function configurarUploaderImagen() {
        const fileInput = document.getElementById('personal-foto-file');
        const filePreview = document.getElementById('personal-foto-preview');
        const previewImg = document.getElementById('personal-foto-preview-img');
        const removeBtn = document.getElementById('btn-remove-image');
        // Hay más de un .file-upload-container en la página (Personal y Mi
        // Negocio) — hay que partir del propio input, no de un querySelector
        // global que siempre agarra el primero del DOM.
        const uploadContainer = fileInput?.closest('.file-upload-container');
        const uploadLabel = uploadContainer?.querySelector('.file-upload-label');

        if (!fileInput) return;
        
        // Manejar selección de archivo
        fileInput.addEventListener('change', function(e) {
            const archivo = e.target.files[0];
            if (archivo) {
                // Validar tipo de archivo
                if (!archivo.type.startsWith('image/')) {
                    mostrarMensajeError('Por favor selecciona un archivo de imagen válido');
                    return;
                }
                
                // Validar tamaño (2MB máximo)
                if (archivo.size > 2 * 1024 * 1024) {
                    mostrarMensajeError('La imagen es demasiado grande. Máximo 2MB permitido.');
                    return;
                }
                
                // Mostrar previsualización
                const reader = new FileReader();
                reader.onload = function(e) {
                    previewImg.src = e.target.result;
                    filePreview.style.display = 'block';
                    uploadLabel.style.display = 'none';
                };
                reader.readAsDataURL(archivo);
            }
        });
        
        // Manejar eliminación de imagen
        removeBtn.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();
            
            fileInput.value = '';
            filePreview.style.display = 'none';
            uploadLabel.style.display = 'flex';
            document.getElementById('personal-foto-url').value = '';
        });
        
        // Drag & drop functionality
        uploadContainer.addEventListener('dragover', function(e) {
            e.preventDefault();
            uploadContainer.classList.add('dragover');
        });
        
        uploadContainer.addEventListener('dragleave', function(e) {
            e.preventDefault();
            uploadContainer.classList.remove('dragover');
        });
        
        uploadContainer.addEventListener('drop', function(e) {
            e.preventDefault();
            uploadContainer.classList.remove('dragover');
            
            const archivos = e.dataTransfer.files;
            if (archivos.length > 0) {
                fileInput.files = archivos;
                fileInput.dispatchEvent(new Event('change'));
            }
        });
    }

    // Uploader del logo/foto del negocio — mismo comportamiento que
    // configurarUploaderImagen() (Personal), con sus propios IDs.
    function configurarUploaderLogoNegocio() {
        const fileInput = document.getElementById('negocio-logo-file');
        const filePreview = document.getElementById('negocio-logo-preview');
        const previewImg = document.getElementById('negocio-logo-preview-img');
        const removeBtn = document.getElementById('btn-remove-negocio-logo');
        const uploadContainer = fileInput?.closest('.file-upload-container');
        const uploadLabel = uploadContainer?.querySelector('.file-upload-label');

        if (!fileInput || !uploadContainer) return;

        fileInput.addEventListener('change', function(e) {
            const archivo = e.target.files[0];
            if (archivo) {
                if (!archivo.type.startsWith('image/')) {
                    mostrarMensajeError('Por favor selecciona un archivo de imagen válido');
                    return;
                }

                if (archivo.size > 2 * 1024 * 1024) {
                    mostrarMensajeError('La imagen es demasiado grande. Máximo 2MB permitido.');
                    return;
                }

                const reader = new FileReader();
                reader.onload = function(e) {
                    previewImg.src = e.target.result;
                    filePreview.style.display = 'block';
                    uploadLabel.style.display = 'none';
                };
                reader.readAsDataURL(archivo);
            }
        });

        removeBtn.addEventListener('click', function(e) {
            e.preventDefault();
            e.stopPropagation();

            fileInput.value = '';
            filePreview.style.display = 'none';
            uploadLabel.style.display = 'flex';
            document.getElementById('negocio-logo-url').value = '';
        });

        uploadContainer.addEventListener('dragover', function(e) {
            e.preventDefault();
            uploadContainer.classList.add('dragover');
        });

        uploadContainer.addEventListener('dragleave', function(e) {
            e.preventDefault();
            uploadContainer.classList.remove('dragover');
        });

        uploadContainer.addEventListener('drop', function(e) {
            e.preventDefault();
            uploadContainer.classList.remove('dragover');

            const archivos = e.dataTransfer.files;
            if (archivos.length > 0) {
                fileInput.files = archivos;
                fileInput.dispatchEvent(new Event('change'));
            }
        });
    }

