    function inicializarGestionMiNegocio() {
        const btnAgregarFeriado = document.getElementById('btn-agregar-feriado');
        if (btnAgregarFeriado) {
            btnAgregarFeriado.addEventListener('click', agregarFeriado);
        }

        const form = document.getElementById('form-mi-negocio');
        if (!form) return;

        configurarUploaderLogoNegocio();

        // El WhatsApp del negocio casi siempre es el mismo teléfono de
        // contacto — autocompletar el link de WhatsApp con cada cambio
        // evita tener que tipear el mismo número dos veces en formatos
        // distintos.
        const inputTelefono = document.getElementById('mi-negocio-telefono');
        const inputWhatsapp = document.getElementById('mi-negocio-whatsapp');
        if (inputTelefono && inputWhatsapp) {
            inputTelefono.addEventListener('input', () => {
                inputWhatsapp.value = telefonoAUrlWhatsapp(inputTelefono.value);
            });
        }

        form.addEventListener('submit', async (e) => {
            e.preventDefault();
            await guardarMiNegocio();
        });
    }

    // Arma el link de wa.me a partir del teléfono de contacto. Asume
    // Argentina (código de país 54 + 9 para celulares, la convención que
    // pide WhatsApp) — si el teléfono ya viene con el 54 puesto, no lo
    // duplica.
    function telefonoAUrlWhatsapp(telefono) {
        const digitos = (telefono || '').replace(/\D/g, '');
        if (!digitos) return '';
        const conCodigoPais = digitos.startsWith('54') ? digitos : `549${digitos}`;
        return `https://wa.me/${conCodigoPais}`;
    }

    // Puebla los campos simples de "Mi Negocio" (los que también puede
    // tocar el superadmin desde su propio panel de configuración). Separado
    // de cargarMiNegocioYMostrar() para reusarlo desde el listener en vivo
    // de más abajo. Con soloSiNoTieneFoco:true no pisa un campo que el
    // dueño esté escribiendo en ese momento.
    function poblarCamposSimplesMiNegocio(negocio, { soloSiNoTieneFoco = false } = {}) {
        const campos = {
            'mi-negocio-telefono': negocio.telefono || '',
            'mi-negocio-direccion': negocio.direccion || '',
            'mi-negocio-email': negocio.email || '',
            'mi-negocio-instagram': negocio.redes?.instagram || '',
            'mi-negocio-facebook': negocio.redes?.facebook || '',
            'mi-negocio-x': negocio.redes?.x || '',
            'mi-negocio-whatsapp': negocio.redes?.whatsapp || ''
        };
        Object.entries(campos).forEach(([id, valor]) => {
            const input = document.getElementById(id);
            if (!input) return;
            if (soloSiNoTieneFoco && document.activeElement === input) return;
            input.value = valor;
        });
    }

    // Se cancela cada vez que se abre "Mi Negocio" de nuevo (evita
    // acumular listeners, mismo motivo que el fix del acordeón del menú)
    // y al salir de la pestaña — ver cambiarSeccion().
    let cancelarEscuchaMiNegocio = null;

    async function cargarMiNegocioYMostrar() {
        const estadoDiv = document.getElementById('mi-negocio-estado');
        if (estadoDiv) {
            estadoDiv.textContent = '';
            estadoDiv.className = 'mi-negocio-estado';
        }

        if (cancelarEscuchaMiNegocio) {
            cancelarEscuchaMiNegocio();
            cancelarEscuchaMiNegocio = null;
        }

        try {
            const negocioRef = db.collection('negocios').doc(obtenerNegocioIdActual());
            const doc = await negocioRef.get();
            if (!doc.exists) return;
            const negocio = doc.data();

            if (negocio.logoUrl) {
                document.getElementById('negocio-logo-url').value = negocio.logoUrl;
                document.getElementById('negocio-logo-preview-img').src = negocio.logoUrl;
                document.getElementById('negocio-logo-preview').style.display = 'block';
                document.querySelector('#negocio-logo-file').closest('.file-upload-container').querySelector('.file-upload-label').style.display = 'none';
            }

            poblarCamposSimplesMiNegocio(negocio);

            // "diasNoLaborables" es el nombre real que lee app.js (con "b").
            // Se admite también el campo viejo mal nombrado ("diasNoLaborales",
            // sin "b") para no perder feriados ya cargados antes de este fix.
            feriadosActuales = normalizarFeriados(negocio.diasNoLaborables ?? negocio.diasNoLaborales);
            mostrarFeriados();

            await inicializarMapaMiNegocio(negocio.coordenadas || null);

            // Si el superadmin cambia teléfono/dirección/email/redes desde
            // su propio panel mientras el dueño tiene esta pestaña abierta,
            // que se refleje solo — antes había que recargar toda la
            // página para verlo.
            cancelarEscuchaMiNegocio = negocioRef.onSnapshot((snap) => {
                if (snap.exists) poblarCamposSimplesMiNegocio(snap.data(), { soloSiNoTieneFoco: true });
            });
        } catch (error) {
            console.error('❌ Error cargando datos del negocio:', error);
        }
    }

    // Normaliza el formato viejo (fechas separadas por coma dentro de un
    // único elemento del array) a un array real de fechas individuales.
    function normalizarFeriados(diasNoLaborales) {
        if (!Array.isArray(diasNoLaborales)) return [];
        return diasNoLaborales
            .flatMap(item => String(item).split(','))
            .map(f => f.trim().replaceAll('/', '-'))
            .filter(Boolean)
            .sort();
    }

    function mostrarFeriados() {
        const listaDiv = document.getElementById('feriados-list');
        if (!listaDiv) return;
        listaDiv.innerHTML = '';

        if (feriadosActuales.length === 0) {
            listaDiv.innerHTML = '<p class="sin-feriados">No hay feriados cargados.</p>';
            return;
        }

        feriadosActuales.forEach((fecha, index) => {
            const item = document.createElement('div');
            item.className = 'feriado-item';
            item.innerHTML = `
                <span>${fecha}</span>
                <button type="button" class="btn-quitar-feriado" data-index="${index}">&times;</button>
            `;
            listaDiv.appendChild(item);
        });

        listaDiv.querySelectorAll('.btn-quitar-feriado').forEach(btn => {
            btn.addEventListener('click', () => {
                feriadosActuales.splice(parseInt(btn.dataset.index, 10), 1);
                mostrarFeriados();
            });
        });
    }

    function agregarFeriado() {
        const input = document.getElementById('mi-negocio-nuevo-feriado');
        const fecha = input.value;
        if (!fecha) return;
        if (!feriadosActuales.includes(fecha)) {
            feriadosActuales.push(fecha);
            feriadosActuales.sort();
            mostrarFeriados();
        }
        input.value = '';
    }

    function cargarGoogleMapsScript() {
        if (window.google && window.google.maps) return Promise.resolve();
        if (window.__googleMapsCargando) return window.__googleMapsCargando;

        window.__googleMapsCargando = new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = `https://maps.googleapis.com/maps/api/js?key=${GOOGLE_MAPS_API_KEY}&loading=async&callback=__onGoogleMapsListo`;
            window.__onGoogleMapsListo = () => resolve();
            script.onerror = () => reject(new Error('No se pudo cargar Google Maps'));
            document.head.appendChild(script);
        });

        return window.__googleMapsCargando;
    }

    async function inicializarMapaMiNegocio(coordenadasIniciales) {
        const contenedor = document.getElementById('mi-negocio-mapa');
        if (!contenedor) return;

        try {
            await cargarGoogleMapsScript();
        } catch (error) {
            console.error('❌ Error cargando Google Maps:', error);
            contenedor.innerHTML = '<p class="sin-feriados">No se pudo cargar el mapa.</p>';
            return;
        }

        const centro = coordenadasIniciales || { lat: -34.6037, lng: -58.3816 }; // Buenos Aires por defecto

        mapaMiNegocio = new google.maps.Map(contenedor, {
            center: centro,
            zoom: coordenadasIniciales ? 15 : 11
        });

        marcadorMiNegocio = new google.maps.Marker({
            position: centro,
            map: mapaMiNegocio,
            draggable: true
        });

        coordenadasPendientesMiNegocio = coordenadasIniciales || null;

        mapaMiNegocio.addListener('click', (e) => {
            const nuevaPos = { lat: e.latLng.lat(), lng: e.latLng.lng() };
            marcadorMiNegocio.setPosition(nuevaPos);
            coordenadasPendientesMiNegocio = nuevaPos;
            autocompletarDireccionDesdeMapa(nuevaPos);
        });

        marcadorMiNegocio.addListener('dragend', () => {
            const pos = marcadorMiNegocio.getPosition();
            const nuevaPos = { lat: pos.lat(), lng: pos.lng() };
            coordenadasPendientesMiNegocio = nuevaPos;
            autocompletarDireccionDesdeMapa(nuevaPos);
        });
    }

    // Cada vez que se marca/arrastra el pin, reemplaza la dirección por la
    // geocodificada de ese punto — el pin es la fuente de verdad de dónde
    // está el local, así que si se mueve, el texto tiene que reflejar
    // exactamente eso (no solo cuando el campo está vacío).
    function autocompletarDireccionDesdeMapa(posicion) {
        const inputDireccion = document.getElementById('mi-negocio-direccion');
        if (!inputDireccion) return;

        new google.maps.Geocoder().geocode({ location: posicion }, (resultados, status) => {
            if (status === 'OK' && resultados[0]) {
                inputDireccion.value = direccionCorta(resultados[0]);
            }
        });
    }

    // El formatted_address del geocoder trae provincia/país/código postal
    // completos (ej. "Av. Corrientes 1234, C1043AAZ, CABA, Argentina") —
    // demasiado largo para un campo de dirección de local. Arma solo
    // "calle + altura, ciudad" a partir de los componentes tipados; si por
    // lo que sea el geocoder no los tiene (zonas rurales, algunos países),
    // cae al formatted_address completo antes que dejarlo vacío.
    function direccionCorta(resultadoGeocoder) {
        const componentes = resultadoGeocoder.address_components || [];
        const calle = componentes.find(c => c.types.includes('route'))?.long_name;
        const altura = componentes.find(c => c.types.includes('street_number'))?.long_name;
        const ciudad = componentes.find(c => c.types.includes('locality'))?.long_name;

        const calleYAltura = calle && altura ? `${calle} ${altura}` : calle;
        if (calleYAltura && ciudad) return `${calleYAltura}, ${ciudad}`;
        if (calleYAltura) return calleYAltura;
        return resultadoGeocoder.formatted_address;
    }

    async function guardarMiNegocio() {
        const btn = document.getElementById('btn-guardar-mi-negocio');
        const estadoDiv = document.getElementById('mi-negocio-estado');

        estadoDiv.textContent = '';
        estadoDiv.className = 'mi-negocio-estado';

        const emailNegocio = document.getElementById('mi-negocio-email').value.trim();
        if (!emailNegocio) {
            estadoDiv.textContent = 'El email de contacto es obligatorio — a él llegan los avisos de reservas y cancelaciones.';
            estadoDiv.className = 'mi-negocio-estado mi-negocio-estado-error';
            return;
        }

        // Firebase Storage rechaza la subida del logo si la sesión expiró o
        // todavía no terminó de resolverse — sin este chequeo, eso llegaba
        // como un "Firebase Storage: User does not have permission..." (ver
        // subirLogoNegocio) que no le dice nada al dueño del negocio.
        if (!firebase.auth().currentUser) {
            estadoDiv.textContent = 'Tu sesión expiró — recargá la página y volvé a iniciar sesión antes de guardar.';
            estadoDiv.className = 'mi-negocio-estado mi-negocio-estado-error';
            return;
        }

        btn.disabled = true;

        try {
            const negocioId = obtenerNegocioIdActual();
            const archivoLogo = document.getElementById('negocio-logo-file').files[0];
            const logoUrlExistente = document.getElementById('negocio-logo-url').value;

            let logoUrl;
            if (archivoLogo) {
                logoUrl = await subirLogoNegocio(archivoLogo, negocioId);
            } else if (logoUrlExistente) {
                logoUrl = logoUrlExistente;
            } else {
                logoUrl = '';
            }

            const datosActualizados = {
                logoUrl,
                telefono: document.getElementById('mi-negocio-telefono').value.trim(),
                direccion: document.getElementById('mi-negocio-direccion').value.trim(),
                email: emailNegocio,
                redes: {
                    instagram: document.getElementById('mi-negocio-instagram').value.trim(),
                    facebook: document.getElementById('mi-negocio-facebook').value.trim(),
                    x: document.getElementById('mi-negocio-x').value.trim(),
                    whatsapp: document.getElementById('mi-negocio-whatsapp').value.trim()
                },
                diasNoLaborables: feriadosActuales
            };

            if (coordenadasPendientesMiNegocio) {
                datosActualizados.coordenadas = coordenadasPendientesMiNegocio;
            }

            await db.collection('negocios').doc(obtenerNegocioIdActual()).update(datosActualizados);

            estadoDiv.textContent = 'Cambios guardados correctamente.';
            estadoDiv.className = 'mi-negocio-estado mi-negocio-estado-exito';
            mostrarMensajeExito('Datos del negocio actualizados');
        } catch (error) {
            console.error('❌ Error guardando datos del negocio:', error);
            estadoDiv.textContent = 'Error al guardar los cambios.';
            estadoDiv.className = 'mi-negocio-estado mi-negocio-estado-error';
        } finally {
            btn.disabled = false;
        }
    }

