                    duracionTurnoBase: parseInt(document.getElementById('config-duracion-turno').value, 10),
                    tipoSenia: document.getElementById('config-tipo-senia').value,
                    señaMinima: parseFloat(document.getElementById('config-sena-minima').value) || 0,
